DROP TABLE IF EXISTS `fza_articulos`;
CREATE TABLE `fza_articulos` (
  `CODIGO_ART_ART` varchar(20) NOT NULL,
  `ESACTIVO_ART` varchar(1) NOT NULL DEFAULT 'S',
  `TIPO_ART` varchar(10) NOT NULL DEFAULT 'ESTANDAR' COMMENT 'ESTANDAR=Físico (Control Stock), SERVICIO=Intangible (Sin Stock), KIT=Pack',
  `DESCRIPCION_ART` varchar(1000) NOT NULL,
  `CODIGO_FAM_ART` varchar(20) NULL DEFAULT NULL,
  `TIPO_IVA_ART` varchar(2) NOT NULL,
  `ESACTIVO_FIJO_ART` varchar(1) NULL DEFAULT 'N',
  `TIPO_CANTIDAD_ART` varchar(20) NOT NULL DEFAULT 'Uds',
  `ESVARIACION_ART` varchar(1) NOT NULL,
  `ESTRAZABLE_ART` varchar(1) NOT NULL DEFAULT 'N' COMMENT 'S=Pide Lote/Caducidad, N=No pide',
  `ORDEN_ART` int(11) NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `TIPO_VARIACION_ART` varchar(20) NULL DEFAULT NULL,
  PRIMARY KEY (`CODIGO_ART_ART`)
);
