DROP TABLE IF EXISTS `fza_articulos_stockactual`;
CREATE TABLE `fza_articulos_stockactual` (
  `CODIGO_ALM_STK` varchar(10) NOT NULL,
  `CODIGO_UNIDAD_STK` varchar(50) NOT NULL,
  `LOTE_STK` varchar(50) NOT NULL DEFAULT '',
  `FECHA_CADUCIDAD_STK` date NULL DEFAULT NULL,
  `CANTIDAD_STK` decimal(19,6) NULL DEFAULT '0.000000',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `VALOR_TOTAL_STK` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_MEDIO_STK` decimal(19,6) NULL DEFAULT '0.000000',
  `CANTIDAD_PTE_RECIBIR_STK` decimal(19,6) NULL DEFAULT '0.000000',
  `CANTIDAD_PTE_SERVIR_STK` decimal(19,6) NULL DEFAULT '0.000000',
  `CANTIDAD_PTE_TRASPASAR_STK` decimal(19,6) NULL DEFAULT '0.000000',
  `CANTIDAD_PTE_RECTRASPASAR_STK` decimal(19,6) NULL DEFAULT '0.000000',
  `CANTIDAD_ENT_COMPRA_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CANTIDAD_ENT_TRASPASO_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CANTIDAD_SAL_TRASPASO_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CANTIDAD_ENT_DEPOSITO_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CANTIDAD_SAL_DEPOSITO_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CANTIDAD_SAL_VENTA_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CANTIDAD_ENT_REGULAR_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CANTIDAD_SAL_ALBVENTA_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CANTIDAD_ENT_ALBENTRADA_STK` decimal(19,6) NOT NULL DEFAULT '0.000000',
  PRIMARY KEY (`CODIGO_ALM_STK`,`CODIGO_UNIDAD_STK`,`LOTE_STK`)
);
ALTER TABLE `fza_articulos_stockactual` ADD INDEX `IDX_STK_UNIDAD` (`CODIGO_UNIDAD_STK`);

