  `ID_ARQR` int(11) NOT NULL AUTO_INCREMENT COMMENT 'PK autoincremental',
  `CODIGO_ARQ_ARQR` varchar(30) NOT NULL COMMENT 'FK lógica a fza_caja_arqueos.CODIGO_ARQ',
  `CODIGO_FP_CFP_ARQR` varchar(20) NOT NULL COMMENT 'FK lógica a fza_caja_formas_pago.CODIGO_FP_CFP',
  `DESCRIPCION_FP_ARQR` varchar(100) NOT NULL DEFAULT '' COMMENT 'Snapshot de DESCRIPCION_FORMA_PAGO_CFP al momento del arqueo',
