  `IMPORTE_RECUENTO_ARQR` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Importe que el usuario ha contado físicamente',
  `DIFERENCIA_ARQR` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Recuento − Sistema (positivo = sobrante)',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_ARQR`)
);
