DROP TABLE IF EXISTS `fza_caja_operaciones`;
CREATE TABLE `fza_caja_operaciones` (
  `ID_OPCAJA` bigint(20) NOT NULL AUTO_INCREMENT,
  `CODIGO_EMP_OPCAJA` varchar(10) NOT NULL,
  `CODIGO_ALM_OPCAJA` varchar(10) NOT NULL,
  `CODIGO_CAJA_OPCAJA` varchar(10) NOT NULL COMMENT 'Terminal físico (TPV1, TPV2...)',
  `NUMERO_OPERACION_OPCAJA` varchar(20) NOT NULL,
  `NUMERO_FAC_OPCAJA` varchar(20) NULL DEFAULT NULL,
  `SERIE_FAC_OPCAJA` varchar(20) NULL DEFAULT NULL,
  `FECHA_OPERACION_OPCAJA` datetime NOT NULL,
  `CODIGO_EMPLEADO_OPCAJA` varchar(20) NOT NULL,
  `TIPO_OPERACION_OPCAJA` varchar(2) NOT NULL COMMENT 'VE, AL, CB, EC, GC, TR, AT',
  `IMPORTE_TOTAL_OPCAJA` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CODIGO_CLI_OPCAJA` varchar(20) NULL DEFAULT NULL,
  `ESTADO_DEVOLUCION_OPCAJA` char(1) NOT NULL DEFAULT 'N',
  `IMPORTE_DEVUELTO_ACUM_OPCAJA` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `CONCEPTO_GASTO_INGRESO_OPCAJA` varchar(100) NULL DEFAULT NULL,
  `SERIE_REF_ORIGEN_OPCAJA` varchar(20) NULL DEFAULT NULL,
  `NUMERO_REF_ORIGEN_OPCAJA` varchar(20) NULL DEFAULT NULL,
  `MOTIVO_DEVOLUCION_OPCAJA` varchar(50) NULL DEFAULT NULL,
  `CODIGO_EMP_CONTRA_OPCAJA` varchar(20) NULL DEFAULT NULL,
  `CODIGO_ALM_CONTRA_OPCAJA` varchar(10) NULL DEFAULT NULL,
  `ESTRASPASO_OPCAJA` varchar(1) NULL DEFAULT 'N',
  `CODIGO_ARQUEO_OPCAJA` varchar(20) NULL DEFAULT NULL COMMENT 'ID del Cierre Z al que pertenece esta línea',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ID_DEPOSITO_OPCAJA` varchar(20) NULL DEFAULT NULL COMMENT 'FK a fza_depositos_cliente, solo en CB y DE de depósitos',
  `FECHA_OP_DIA_OPCAJA` date NULL DEFAULT NULL,
  PRIMARY KEY (`ID_OPCAJA`)
);
