-- Tabla: fza_clientes

DROP TABLE IF EXISTS `fza_clientes`;
CREATE TABLE `fza_clientes` (
  `CODIGO_CLI_CLI` varchar(20) NOT NULL,
  `ESACTIVO_CLI` varchar(1) NULL DEFAULT 'S',
  `ORDEN_CLI` int(11) NULL DEFAULT NULL,
  `RAZON_SOCIAL_CLI` varchar(200) NOT NULL,
  `NIF_CLI` varchar(50) NULL DEFAULT NULL,
  `MOVIL_CLI` varchar(40) NULL DEFAULT NULL,
  `EMAIL_CLI` varchar(200) NULL DEFAULT NULL,
  `DIRECCION1_CLI` varchar(200) NULL DEFAULT NULL,
  `DIRECCION2_CLI` varchar(200) NULL DEFAULT NULL,
  `POBLACION_CLI` varchar(200) NULL DEFAULT NULL,
  `PROVINCIA_CLI` varchar(200) NULL DEFAULT NULL,
  `CODIGO_POSTAL_CLI` varchar(15) NULL DEFAULT NULL,
  `CODIGO_PAI_CLI` varchar(3) NULL DEFAULT '724',
  `NOMBRE_PAI_CLI` varchar(150) NULL DEFAULT 'España',
  `OBSERVACIONES_CLI` text NULL DEFAULT NULL,
  `REFERENCIA_CLI` varchar(100) NULL DEFAULT NULL,
  `CONTACTO_CLI` varchar(100) NULL DEFAULT NULL,
  `TELEFONO_CONTACTO_CLI` varchar(100) NULL DEFAULT NULL,
  `TELEFONO_CLI` varchar(40) NULL DEFAULT NULL,
  `IBAN_CLI` varchar(100) NULL DEFAULT NULL,
  `ESIVA_RECARGO_CLI` varchar(1) NULL DEFAULT 'N',
  `ESRETENCIONES_CLI` varchar(1) NULL DEFAULT 'S',
  `TOTAL_LIMITE_CREDITO_CLI` decimal(19,6) NULL DEFAULT NULL,
  `ESPERMITE_DEUDA_CLI` varchar(1) NULL DEFAULT NULL,
  `TOTAL_DEUDA_CLI` decimal(19,6) NULL DEFAULT NULL,
  `ESIVA_EXENTO_CLI` varchar(1) NULL DEFAULT 'N',
  `ESINTRACOMUNITARIO_CLI` varchar(1) NULL DEFAULT 'N',
  `ESREGIMENESPECIALAGRICOLA_CLI` varchar(1) NULL DEFAULT 'N',
  `CODIGO_FP_CLI` varchar(20) NULL DEFAULT NULL,
  `TARIFA_ARTICULO_CLI` varchar(10) NULL DEFAULT NULL,
  `SERIE_CON_CLI` varchar(8) NULL DEFAULT NULL,
  `TEXTO_LEGAL_FACTURA_CLI` varchar(1000) NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_CLI_CLI`)
);
ALTER TABLE `fza_clientes` ADD INDEX `FT_CLI_RAZON` (`RAZON_SOCIAL_CLI`);
ALTER TABLE `fza_clientes` ADD INDEX `IDX_CLIENTES_EMAIL` (`EMAIL_CLI`);
