-- Tabla: fza_depositos_cliente

DROP TABLE IF EXISTS `fza_depositos_cliente`;
CREATE TABLE `fza_depositos_cliente` (
  `ID_DEPOSITO_DEP` varchar(20) NOT NULL,
  `CODIGO_EMP_DEP` varchar(20) NOT NULL,
  `CODIGO_CLI_DEP` varchar(20) NOT NULL,
  `CODIGO_ART_DEP` varchar(50) NOT NULL,
  `CODIGO_UNIDAD_DEP` varchar(50) NOT NULL COMMENT 'SKU o Código de Barras único de la talla/color',
  `CODIGO_ALM_DEP` varchar(10) NULL DEFAULT NULL COMMENT 'Almacén de depósito donde está físicamente la prenda',
  `PRECIO_VENTA_DEP` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Precio Unidad original de la venta',
  `IMPORTE_ANTICIPO_DEP` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Dinero acumulado entregado a cuenta hasta la fecha',
  `ESTADO_DEP` varchar(15) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'Valores: PENDIENTE, CERRADO',
  `FECHA_CREACION_DEP` datetime NOT NULL DEFAULT current_timestamp(),
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `TIPO_IVA_DEP` char(1) NOT NULL DEFAULT 'N',
  `PORCENTAJE_IVA_DEP` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `ESIMP_INCL_DEP` char(1) NOT NULL DEFAULT 'S',
  `CANTIDAD_PENDIENTE_DEP` decimal(19,6) NULL DEFAULT NULL COMMENT 'Cantidad de artículos comprados',
  `FECHA_ENTREGA_DEP` date NULL DEFAULT NULL,
  `CODIGO_CAJA_DEP` varchar(10) NULL DEFAULT NULL COMMENT 'Caja donde se realizó el depósito',
  `NUMERO_OPERACION_DEP` varchar(20) NULL DEFAULT NULL COMMENT 'Número de operación de caja en la creación',
  `EMPRESA_CANCEL_DEP` varchar(20) NULL DEFAULT NULL COMMENT 'Empresa donde se canceló el depósito',
  `ALMACEN_CANCEL_DEP` varchar(10) NULL DEFAULT NULL COMMENT 'Almacén donde se canceló el depósito',
  `CAJA_CANCEL_DEP` varchar(10) NULL DEFAULT NULL COMMENT 'Caja donde se canceló el depósito',
  `NUMERO_OPERACION_CANCEL_DEP` varchar(20) NULL DEFAULT NULL COMMENT 'Número de operación de la cancelación',
  PRIMARY KEY (`ID_DEPOSITO_DEP`)
);
ALTER TABLE `fza_depositos_cliente` ADD INDEX `IDX_DEP_CLIENTE` (`CODIGO_CLI_DEP`, `ESTADO_DEP`);
ALTER TABLE `fza_depositos_cliente` ADD INDEX `IDX_DEP_OP_ALTA` (`CODIGO_EMP_DEP`, `CODIGO_ALM_DEP`, `CODIGO_CAJA_DEP`, `NUMERO_OPERACION_DEP`);
ALTER TABLE `fza_depositos_cliente` ADD INDEX `IDX_DEP_OP_CANCEL` (`EMPRESA_CANCEL_DEP`, `ALMACEN_CANCEL_DEP`, `CAJA_CANCEL_DEP`, `NUMERO_OPERACION_CANCEL_DEP`);
ALTER TABLE `fza_depositos_cliente` ADD INDEX `IDX_DEP_OP_FECHA` (`CODIGO_EMP_DEP`, `CODIGO_ALM_DEP`, `CODIGO_CAJA_DEP`, `FECHA_CREACION_DEP`);
ALTER TABLE `fza_depositos_cliente` ADD INDEX `IDX_DEP_UNIDAD` (`CODIGO_UNIDAD_DEP`, `ESTADO_DEP`);

