  ('229', 'familias_codigo_padre', '-- =============================================================================
-- Anade columna CODIGO_PADRE_FAM a fza_articulos_familias
-- =============================================================================
-- El ERP legacy modela la jerarquia de familias en 2 niveles dentro de
-- la tabla ocniv:
--   - Nivel 2 = SECCION    (codigo de 2 chars: "01" SEÑORA, "14"
--                            UNIFORME INMACULADA CONCEP., ...)
--   - Nivel 4 = FAMILIA    (codigo de 4 chars: "1401" FALDA INMACULADA
--                            CONCEP., "1403" JERSEY..., "0101" BLUSA...)
--
-- Los 2 primeros chars del codigo Nivel=4 son SIEMPRE el codigo de la
-- seccion padre (Nivel=2). Para preservar esa jerarquia en destino
-- anadimos CODIGO_PADRE_FAM, que apunta a la familia padre dentro de
-- la propia tabla.
--
-- Convencion de nombre: CODIGO_PADRE_FAM (sin sufijo de tabla extra,
-- ver §3.3 de LIBRO_DE_ESTILO_BBDD.md — el sufijo de la tabla es FAM
-- y "PADRE" es el nucleo).
--
-- Idempotente: ALTER se ejecuta solo si la columna no existe.
-- =============================================================================

SET @sExisteCol := (
  SELECT COUNT(*)
    FROM INFORMATION_SCHEMA.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_articulos_familias''
     AND COLUMN_NAME  = ''CODIGO_PADRE_FAM''
);

SET @sSql := IF(@sExisteCol = 0,
  ''ALTER TABLE fza_articulos_familias
     ADD COLUMN CODIGO_PADRE_FAM varchar(20) NULL DEFAULT NULL
     AFTER CODIGO_FAM_FAM'',
  ''SELECT ''''CODIGO_PADRE_FAM ya existe, se omite'''' AS info''
);

PREPARE stmt FROM @sSql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- Indice para acelerar la navegacion padre → hijos
SET @sExisteIdx := (
  SELECT COUNT(*)
    FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_articulos_familias''
     AND INDEX_NAME   = ''IDX_FAM_PADRE''
);

SET @sSqlIdx := IF(@sExisteIdx = 0,
  ''ALTER TABLE fza_articulos_familias
     ADD INDEX IDX_FAM_PADRE (CODIGO_PADRE_FAM)'',
  ''SELECT ''''IDX_FAM_PADRE ya existe, se omite'''' AS info''
);

PREPARE stmt FROM @sSqlIdx;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
', '2026-05-20 07:36:25', '2026-05-20 07:36:25', 'Administrador', 'Administrador'),
  ('230', 'widen_linea_invlin', '-- =============================================================================
-- Ampliar fza_inventarios_lineas.LINEA_INVLIN a varchar(8)
-- =============================================================================
-- La columna esta declarada varchar(4) (rango ''0001''..''9999'') pero un
-- inventario inicial migrado desde un legacy grande puede tener decenas
-- de miles de lineas en el mismo (Empresa, Almacen). Al pasar la fila
-- 10000 el migrador genera "10000" (5 chars) y el INSERT revienta con:
--
--   EMySqlNetException #22001 ''Data too long for column LINEA_INVLIN''
--
-- Ampliamos a varchar(8): cabe hasta 99 999 999 lineas por documento,
-- mas que suficiente y sigue siendo compacto.
--
-- Idempotente: el ALTER solo se ejecuta si la columna actual mide < 8.
-- =============================================================================

SET @sLen := (
  SELECT CHARACTER_MAXIMUM_LENGTH
    FROM INFORMATION_SCHEMA.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_inventarios_lineas''
     AND COLUMN_NAME  = ''LINEA_INVLIN''
);

SET @sSql := IF(@sLen IS NOT NULL AND @sLen < 8,
  ''ALTER TABLE fza_inventarios_lineas
     MODIFY COLUMN LINEA_INVLIN varchar(8) NOT NULL
       COMMENT ''''Secuencial de la línea (00000001, 00000002...)'''''',
  ''SELECT ''''LINEA_INVLIN ya tiene >= 8, se omite'''' AS info'');

PREPARE stmt FROM @sSql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
', '2026-05-20 09:06:33', '2026-05-20 09:06:33', 'Administrador', 'Administrador'),
  ('231', 'fix_sps_inventarios_v_linea', '-- =============================================================================
-- Fix v_LINEA VARCHAR(4) -> VARCHAR(8) en las SPs de regularizacion
-- =============================================================================
-- Companero de widen_linea_invlin.sql. Aquel ampliaba la columna
-- fza_inventarios_lineas.LINEA_INVLIN a varchar(8) y el migrador empezo
-- a generar lineas con Format(''%.8d'', ...). Pero las stored procedures
-- de regularizacion seguian con:
--
--     DECLARE v_LINEA VARCHAR(4);
--
-- El FETCH del cursor trunca silenciosamente ''00000001'' -> ''0000''.
-- Consecuencias:
--   1. PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO: el UPDATE final
--      "WHERE LINEA_INVLIN = v_LINEA" no matchea ninguna fila, asi que
--      ni CANTIDAD_TEORICA, ni DIFERENCIA, ni TOTAL_COSTE_DIFERENCIA se
--      actualizan jamas.
--   2. PRC_FZA_INVENTARIOS_APLICAR (que llama a la anterior) cree que
--      ninguna linea tiene diferencia, ejecuta la purga
--      (CANTIDAD_DIFERENCIA = 0 AND TOTAL_COSTE = 0) y deja el
--      inventario sin lineas, marca ESTADO_INV = ''APLICADO'' y nunca
--      genera movimientos en el Kardex.
--
-- Sintoma percibido: "regularizar no hace nada, el inventario pasa a
-- APLICADO sin generar movimientos y las lineas desaparecen".
--
-- Recreamos ambas SPs identicas a las del dump, cambiando solo el ancho
-- de v_LINEA a VARCHAR(8). DROP IF EXISTS las hace idempotentes.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO`;
DELIMITER ;;
CREATE  PROCEDURE `PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO`(
    IN p_EMPRESA VARCHAR(10),
    IN p_ALMACEN VARCHAR(10),
    IN p_SERIE   VARCHAR(20),
    IN p_NRO     VARCHAR(20),
    IN p_USUARIO VARCHAR(100)
)
BEGIN
    DECLARE v_DONE INT DEFAULT FALSE;
    DECLARE v_ESTADO VARCHAR(20);
    DECLARE v_FECHA_CABECERA DATETIME;
    DECLARE v_FECHA_DEFECTO  DATETIME;

    DECLARE v_LINEA          VARCHAR(8);
    DECLARE v_SKU            VARCHAR(50);
    DECLARE v_FISICA         DECIMAL(19,6);
    DECLARE v_PMP_NUEVO      DECIMAL(19,6);
    DECLARE v_FECHA_RECUENTO DATETIME;

    DECLARE v_STOCK_HIST     DECIMAL(19,6);
    DECLARE v_PMP_HIST       DECIMAL(19,6);
    DECLARE v_DIF_CANTIDAD   DECIMAL(19,6);
    DECLARE v_TOTAL_COSTE_DIF DECIMAL(19,6);

    DECLARE cur_lineas CURSOR FOR
        SELECT LINEA_INVLIN,
               CODIGO_UNIDAD_INVLIN,
               CANTIDAD_FISICA_INVLIN,
               PRECIO_MEDIO_NUEVO_INVLIN,
               FECHA_RECUENTO_INVLIN
          FROM fza_inventarios_lineas
         WHERE CODIGO_EMP_INVLIN = p_EMPRESA
           AND CODIGO_ALM_INVLIN = p_ALMACEN
           AND SERIE_INV_INVLIN  = p_SERIE
           AND NUMERO_INV_INVLIN = p_NRO;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_DONE = TRUE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SELECT ESTADO_INV, FECHA_INV
      INTO v_ESTADO, v_FECHA_CABECERA
      FROM fza_inventarios
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO
       FOR UPDATE;

    IF v_ESTADO != ''ABIERTO'' THEN
        SIGNAL SQLSTATE ''45000''
          SET MESSAGE_TEXT = ''Error: El inventario no esta ABIERTO, no se puede recalcular.'';
    END IF;

    SET v_FECHA_DEFECTO = TIMESTAMP(DATE_SUB(DATE(v_FECHA_CABECERA), INTERVAL 1 DAY), ''23:59:59'');

    OPEN cur_lineas;

    read_loop: LOOP
        FETCH cur_lineas
         INTO v_LINEA, v_SKU, v_FISICA, v_PMP_NUEVO, v_FECHA_RECUENTO;

        IF v_DONE THEN
            LEAVE read_loop;
        END IF;

        IF v_FECHA_RECUENTO IS NULL THEN
            SET v_FECHA_RECUENTO = v_FECHA_DEFECTO;
        END IF;

        SET v_STOCK_HIST = 0;
        SET v_PMP_HIST   = 0;

        BEGIN
            DECLARE CONTINUE HANDLER FOR NOT FOUND BEGIN END;
            SELECT IFNULL(SUM(IF(TIPO_MOV = ''E'', CANTIDAD_MOV, -CANTIDAD_MOV)), 0)
              INTO v_STOCK_HIST
              FROM fza_movimientos_almacen
             WHERE CODIGO_ALM_MOV    = p_ALMACEN
               AND CODIGO_UNIDAD_MOV = v_SKU
               AND FECHA_MOV        <= v_FECHA_RECUENTO
               AND ESACTIVO_MOV      = ''S'';
        END;

        BEGIN
            DECLARE CONTINUE HANDLER FOR NOT FOUND BEGIN END;
            SELECT IFNULL(PRECIO_MEDIO_MOV, 0)
              INTO v_PMP_HIST
              FROM fza_movimientos_almacen
             WHERE CODIGO_ALM_MOV    = p_ALMACEN
               AND CODIGO_UNIDAD_MOV = v_SKU
               AND FECHA_MOV        <= v_FECHA_RECUENTO
               AND ESACTIVO_MOV      = ''S''
             ORDER BY FECHA_MOV DESC, NUMERO_MOV DESC
             LIMIT 1;
        END;

        SET v_DIF_CANTIDAD = v_FISICA - v_STOCK_HIST;

        IF v_PMP_NUEVO = 0 OR v_PMP_NUEVO IS NULL THEN
            SET v_PMP_NUEVO = v_PMP_HIST;
        END IF;

        SET v_TOTAL_COSTE_DIF = (v_FISICA * v_PMP_NUEVO) - (v_STOCK_HIST * v_PMP_HIST);

        UPDATE fza_inventarios_lineas
           SET CANTIDAD_TEORICA_INVLIN       = v_STOCK_HIST,
               PRECIO_MEDIO_INVLIN           = v_PMP_HIST,
               PRECIO_MEDIO_NUEVO_INVLIN     = v_PMP_NUEVO,
               CANTIDAD_DIFERENCIA_INVLIN    = v_DIF_CANTIDAD,
               TOTAL_COSTE_DIFERENCIA_INVLIN = v_TOTAL_COSTE_DIF,
               FECHA_RECUENTO_INVLIN         = v_FECHA_RECUENTO,
               USUARIO_MODIF                 = p_USUARIO,
               INSTANTE_MODIF                = NOW()
         WHERE CODIGO_EMP_INVLIN = p_EMPRESA
           AND CODIGO_ALM_INVLIN = p_ALMACEN
           AND SERIE_INV_INVLIN  = p_SERIE
           AND NUMERO_INV_INVLIN = p_NRO
           AND LINEA_INVLIN      = v_LINEA;

    END LOOP;

    CLOSE cur_lineas;

    /* NOTA: ya NO borramos lineas sin diferencia aqui. La purga se hace */
    /* en PRC_FZA_INVENTARIOS_APLICAR, justo antes de generar los movimientos. */

    UPDATE fza_inventarios
       SET TOTAL_UNIDADES_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(CANTIDAD_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas
                WHERE CODIGO_EMP_INVLIN = p_EMPRESA
                  AND CODIGO_ALM_INVLIN = p_ALMACEN
                  AND SERIE_INV_INVLIN  = p_SERIE
                  AND NUMERO_INV_INVLIN = p_NRO
           ),
           TOTAL_EUROS_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(TOTAL_COSTE_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas
                WHERE CODIGO_EMP_INVLIN = p_EMPRESA
                  AND CODIGO_ALM_INVLIN = p_ALMACEN
                  AND SERIE_INV_INVLIN  = p_SERIE
                  AND NUMERO_INV_INVLIN = p_NRO
           ),
           USUARIO_MODIF  = p_USUARIO,
           INSTANTE_MODIF = NOW()
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    COMMIT;
END ;;
DELIMITER ;

-- -----------------------------------------------------------------------------
-- PRC_FZA_INVENTARIOS_APLICAR
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_APLICAR`;
DELIMITER ;;
CREATE  PROCEDURE `PRC_FZA_INVENTARIOS_APLICAR`(
    IN p_EMPRESA VARCHAR(10),
    IN p_ALMACEN VARCHAR(10),
    IN p_SERIE   VARCHAR(20),
    IN p_NRO     VARCHAR(20),
    IN p_USUARIO VARCHAR(100)
)
BEGIN
    DECLARE v_DONE   INT DEFAULT FALSE;
    DECLARE v_ESTADO VARCHAR(20);
    DECLARE v_FECHA_CABECERA DATETIME;
    DECLARE v_FECHA_DEFECTO  DATETIME;

    DECLARE v_LINEA     VARCHAR(8);
    DECLARE v_ARTICULO  VARCHAR(20);
    DECLARE v_SKU       VARCHAR(50);
    DECLARE v_TEORICA   DECIMAL(19,6);
    DECLARE v_FISICA    DECIMAL(19,6);
    DECLARE v_PMP_HIST  DECIMAL(19,6);
    DECLARE v_PMP_NUEVO DECIMAL(19,6);
    DECLARE v_FECHA_RECUENTO DATETIME;
    DECLARE v_FECHA_SALIDA   DATETIME;

    DECLARE v_MOV_SALIDA  VARCHAR(20);
    DECLARE v_MOV_ENTRADA VARCHAR(20);

    DECLARE cur_lineas CURSOR FOR
        SELECT l.LINEA_INVLIN,
               l.CODIGO_ART_INVLIN,
               l.CODIGO_UNIDAD_INVLIN,
               l.CANTIDAD_TEORICA_INVLIN,
               l.CANTIDAD_FISICA_INVLIN,
               l.PRECIO_MEDIO_INVLIN,
               l.PRECIO_MEDIO_NUEVO_INVLIN,
               l.FECHA_RECUENTO_INVLIN
          FROM fza_inventarios_lineas l
         WHERE l.CODIGO_EMP_INVLIN = p_EMPRESA
           AND l.CODIGO_ALM_INVLIN = p_ALMACEN
           AND l.SERIE_INV_INVLIN  = p_SERIE
           AND l.NUMERO_INV_INVLIN = p_NRO;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_DONE = TRUE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    CALL PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO(
        p_EMPRESA, p_ALMACEN, p_SERIE, p_NRO, p_USUARIO
    );

    START TRANSACTION;

    SELECT ESTADO_INV, FECHA_INV
      INTO v_ESTADO, v_FECHA_CABECERA
      FROM fza_inventarios
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO
       FOR UPDATE;

    IF v_ESTADO != ''ABIERTO'' THEN
        SIGNAL SQLSTATE ''45000''
          SET MESSAGE_TEXT = ''Error: El inventario ya fue aplicado o esta cancelado.'';
    END IF;

    SET v_FECHA_DEFECTO = TIMESTAMP(DATE_SUB(DATE(v_FECHA_CABECERA), INTERVAL 1 DAY), ''23:59:59'');

    DELETE FROM fza_inventarios_lineas
     WHERE CODIGO_EMP_INVLIN              = p_EMPRESA
       AND CODIGO_ALM_INVLIN              = p_ALMACEN
       AND SERIE_INV_INVLIN               = p_SERIE
       AND NUMERO_INV_INVLIN              = p_NRO
       AND IFNULL(CANTIDAD_DIFERENCIA_INVLIN,    0) = 0
       AND IFNULL(TOTAL_COSTE_DIFERENCIA_INVLIN, 0) = 0;

    UPDATE fza_inventarios
       SET TOTAL_UNIDADES_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(CANTIDAD_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas
                WHERE CODIGO_EMP_INVLIN = p_EMPRESA
                  AND CODIGO_ALM_INVLIN = p_ALMACEN
                  AND SERIE_INV_INVLIN  = p_SERIE
                  AND NUMERO_INV_INVLIN = p_NRO
           ),
           TOTAL_EUROS_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(TOTAL_COSTE_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas
                WHERE CODIGO_EMP_INVLIN = p_EMPRESA
                  AND CODIGO_ALM_INVLIN = p_ALMACEN
                  AND SERIE_INV_INVLIN  = p_SERIE
                  AND NUMERO_INV_INVLIN = p_NRO
           )
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    OPEN cur_lineas;

    read_loop: LOOP
        FETCH cur_lineas
         INTO v_LINEA, v_ARTICULO, v_SKU, v_TEORICA, v_FISICA, v_PMP_HIST, v_PMP_NUEVO, v_FECHA_RECUENTO;

        IF v_DONE THEN
            LEAVE read_loop;
        END IF;

        IF v_FECHA_RECUENTO IS NULL THEN
            SET v_FECHA_RECUENTO = v_FECHA_DEFECTO;
        END IF;

        SET v_FECHA_SALIDA = DATE_SUB(v_FECHA_RECUENTO, INTERVAL 1 SECOND);
        SET v_MOV_SALIDA  = LEFT(CONCAT(''IV-'', p_NRO, ''-'', v_LINEA, ''S''), 20);
        SET v_MOV_ENTRADA = LEFT(CONCAT(''IV-'', p_NRO, ''-'', v_LINEA, ''E''), 20);

        IF v_TEORICA <> 0 THEN
            CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT(
                v_MOV_SALIDA, ''IN'', p_SERIE, p_NRO, v_LINEA,
                p_EMPRESA, p_ALMACEN, NULL, v_SKU,
                ''S'', v_TEORICA, v_PMP_HIST, (v_TEORICA * v_PMP_HIST),
                p_USUARIO, p_ALMACEN, NULL, NULL, NULL, v_ARTICULO
            );
            UPDATE fza_movimientos_almacen
               SET FECHA_MOV = v_FECHA_SALIDA
             WHERE NUMERO_MOV = v_MOV_SALIDA;
        END IF;

        IF v_FISICA > 0 THEN
            CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT(
                v_MOV_ENTRADA, ''IN'', p_SERIE, p_NRO, v_LINEA,
                p_EMPRESA, p_ALMACEN, NULL, v_SKU,
                ''E'', v_FISICA, v_PMP_NUEVO, (v_FISICA * v_PMP_NUEVO),
                p_USUARIO, p_ALMACEN, NULL, NULL, NULL, v_ARTICULO
            );
            UPDATE fza_movimientos_almacen
               SET FECHA_MOV = v_FECHA_RECUENTO
             WHERE NUMERO_MOV = v_MOV_ENTRADA;
        END IF;

        CALL SP_RECALCULAR_PMP_SKU_ALMACEN(p_EMPRESA, v_SKU, p_ALMACEN);

    END LOOP;

    CLOSE cur_lineas;

    UPDATE fza_inventarios
       SET ESTADO_INV     = ''APLICADO'',
           USUARIO_MODIF  = p_USUARIO,
           INSTANTE_MODIF = NOW()
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    COMMIT;
END ;;
DELIMITER ;
', '2026-05-20 18:06:38', '2026-05-20 18:06:38', 'Administrador', 'Administrador'),
  ('232', 'optimizar_recalculo_pmp', '-- =============================================================================
-- Optimizar recalculo PMP en aplicar / eliminar regularizacion de inventario
-- =============================================================================
-- Sustituye el cursor anidado de SP_RECALCULAR_PMP_SKU_ALMACEN +
-- PRC_FZA_INVENTARIOS_ELIMINAR_REGUL + PRC_FZA_INVENTARIOS_APLICAR por una
-- pasada en conjunto (set-based) sobre todos los SKUs afectados.
--
-- Antes:
--   PRC_FZA_INVENTARIOS_ELIMINAR_REGUL recorre los SKUs afectados con cursor
--   y por cada uno llama a SP_RECALCULAR_PMP_SKU_ALMACEN, que a su vez abre
--   otro cursor y lanza N UPDATE individuales (uno por movimiento) +
--   1 INSERT...ON DUPLICATE en stockactual. Para 50 SKUs con 200 movs cada
--   uno son ~10.000 statements y otros tantos X-locks `FOR UPDATE`.
--
-- Despues:
--   SP_RECALCULAR_PMP_LOTE_ALMACEN procesa todos los SKUs registrados en una
--   tabla temporal `tmp_skus_recalc` con 4 statements grandes:
--     1) volcado ordenado a `tmp_movs_ord` (PK auto-incremental garantiza el
--        orden secuencial),
--     2) UPDATE en lote con variables de sesion para el PMP acumulado
--        (reset al cambiar de SKU),
--     3) UPDATE...JOIN para volcar PRECIO_MEDIO_MOV / TOTAL_COSTE_MOV,
--     4) INSERT...ON DUPLICATE KEY UPDATE en fza_articulos_stockactual desde
--        el ultimo movimiento de cada SKU.
--
-- SP_RECALCULAR_PMP_SKU_ALMACEN se conserva con la misma firma como wrapper
-- (algun llamante futuro podria seguir esperando esa interfaz; hoy solo lo
-- usan los dos PRC_FZA_INVENTARIOS_*, que pasan a llamar directamente al
-- lote, pero el wrapper sigue ahi por compatibilidad).
--
-- Comportamiento funcional identico al original:
--   - Misma formula de PMP (entrada con stock<=0: pmp=coste; entrada con
--     stock>0: media ponderada; salida: pmp invariable).
--   - Mismo TOTAL_COSTE_MOV (cant*coste en entradas, cant*pmp en salidas).
--   - Mismo stockactual final por SKU.
--   - SKUs cuyos movs se han borrado por completo quedan a 0 en stockactual.
--
-- Idempotente: solo recrea procedimientos. `DROP PROCEDURE IF EXISTS` antes
-- de cada `CREATE PROCEDURE`. No cambia esquema. Se puede ejecutar varias
-- veces sin efectos secundarios.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- SP_RECALCULAR_PMP_LOTE_ALMACEN
-- -----------------------------------------------------------------------------
-- Recalcula PMP y stockactual de todos los SKUs presentes en la tabla
-- temporal `tmp_skus_recalc(sku VARCHAR(50) PRIMARY KEY)`, que el llamante
-- debe crear y poblar antes de invocar este procedimiento.
--
-- El procedimiento no abre transaccion: respeta la transaccion del llamante
-- (PRC_FZA_INVENTARIOS_APLICAR / PRC_FZA_INVENTARIOS_ELIMINAR_REGUL ya la
-- abren).
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `SP_RECALCULAR_PMP_LOTE_ALMACEN`;
DELIMITER ;;
CREATE PROCEDURE `SP_RECALCULAR_PMP_LOTE_ALMACEN`(
    IN p_EMPRESA VARCHAR(20),
    IN p_ALMACEN VARCHAR(10)
)
BEGIN
    /* 1. Tabla con todos los movs de los SKUs afectados, ordenados.
       El INSERT...SELECT ORDER BY garantiza el orden de RN secuencial
       (RN es AUTO_INCREMENT como PK clustered en InnoDB). */
    DROP TEMPORARY TABLE IF EXISTS tmp_movs_ord;
    CREATE TEMPORARY TABLE tmp_movs_ord (
        RN                        BIGINT          NOT NULL AUTO_INCREMENT,
        NUMERO_MOV                VARCHAR(20)     NOT NULL,
        CODIGO_UNIDAD_MOV         VARCHAR(50)     NOT NULL,
        TIPO_MOV                  VARCHAR(1)      NOT NULL,
        CANTIDAD_MOV              DECIMAL(19,6)   NOT NULL,
        PRECIO_COSTE_UNITARIO_MOV DECIMAL(19,6)   NOT NULL,
        PMP_NUEVO                 DECIMAL(19,6)   NOT NULL DEFAULT 0,
        STOCK_NUEVO               DECIMAL(19,6)   NOT NULL DEFAULT 0,
        COSTE_NUEVO               DECIMAL(19,6)   NOT NULL DEFAULT 0,
        SKU_PREV                  VARCHAR(50)     NULL,
        PRIMARY KEY (RN),
        KEY IDX_NUMMOV (NUMERO_MOV),
        KEY IDX_SKU    (CODIGO_UNIDAD_MOV)
    ) ENGINE=InnoDB;

    INSERT INTO tmp_movs_ord
        (NUMERO_MOV, CODIGO_UNIDAD_MOV, TIPO_MOV, CANTIDAD_MOV,
         PRECIO_COSTE_UNITARIO_MOV)
    SELECT m.NUMERO_MOV,
           m.CODIGO_UNIDAD_MOV,
           m.TIPO_MOV,
           IFNULL(m.CANTIDAD_MOV, 0),
           IFNULL(m.PRECIO_COSTE_UNITARIO_MOV, 0)
      FROM fza_movimientos_almacen m
      JOIN tmp_skus_recalc s ON s.sku = m.CODIGO_UNIDAD_MOV
     WHERE m.CODIGO_ALM_MOV = p_ALMACEN
     ORDER BY m.CODIGO_UNIDAD_MOV, m.FECHA_MOV, m.INSTANTE_ALTA;

    /* 2. Calculo acumulado por SKU con variables de sesion. El ORDER BY RN
       fuerza el barrido secuencial por la PK clustered. Las asignaciones del
       SET se evaluan de izquierda a derecha: primero PMP_NUEVO (usa @stock y
       @pmp todavia con valor de la fila anterior + @sku_prev de la fila
       anterior para detectar cambio), luego COSTE_NUEVO (usa el @pmp recien
       calculado), luego STOCK_NUEVO (actualiza @stock), y al final SKU_PREV
       actualiza @sku_prev para la siguiente fila. */
    SET @sku_prev := '''';
    SET @stock    := 0;
    SET @pmp      := 0;

    UPDATE tmp_movs_ord
       SET PMP_NUEVO = (
               @pmp := IF(
                   @sku_prev <> CODIGO_UNIDAD_MOV,
                   /* Cambio de SKU: empezamos desde cero */
                   IF(TIPO_MOV = ''E'', PRECIO_COSTE_UNITARIO_MOV, 0),
                   /* Mismo SKU que la fila anterior */
                   IF(TIPO_MOV = ''E'',
                       IF(@stock <= 0,
                           PRECIO_COSTE_UNITARIO_MOV,
                           ((@stock * @pmp)
                              + (CANTIDAD_MOV * PRECIO_COSTE_UNITARIO_MOV))
                            / (@stock + CANTIDAD_MOV)),
                       @pmp
                   )
               )
           ),
           COSTE_NUEVO = IF(TIPO_MOV = ''E'',
                            CANTIDAD_MOV * PRECIO_COSTE_UNITARIO_MOV,
                            CANTIDAD_MOV * @pmp),
           STOCK_NUEVO = (
               @stock := IF(
                   @sku_prev <> CODIGO_UNIDAD_MOV,
                   /* Cambio de SKU: stock empieza en 0 y se suma este mov */
                   IF(TIPO_MOV = ''E'', CANTIDAD_MOV, -CANTIDAD_MOV),
                   IF(TIPO_MOV = ''E'', @stock + CANTIDAD_MOV,
                                       @stock - CANTIDAD_MOV)
               )
           ),
           SKU_PREV = (@sku_prev := CODIGO_UNIDAD_MOV)
     ORDER BY RN;

    /* 3. Volcado en lote a fza_movimientos_almacen. Un solo UPDATE...JOIN
       toma X-locks sobre los movs afectados y los libera al terminar. */
    UPDATE fza_movimientos_almacen m
      JOIN tmp_movs_ord t ON t.NUMERO_MOV = m.NUMERO_MOV
       SET m.PRECIO_MEDIO_MOV = t.PMP_NUEVO,
           m.TOTAL_COSTE_MOV  = t.COSTE_NUEVO;

    /* 4. Stock final por SKU: el ultimo mov (RN maximo) tiene el stock y
       el PMP acumulados al final del historico. Volcamos a stockactual. */
    INSERT INTO fza_articulos_stockactual
        (CODIGO_ALM_STK, CODIGO_UNIDAD_STK,
         CANTIDAD_STK, VALOR_TOTAL_STK, PRECIO_MEDIO_STK, INSTANTE_MODIF)
    SELECT p_ALMACEN,
           t.CODIGO_UNIDAD_MOV,
           t.STOCK_NUEVO,
           IF(t.STOCK_NUEVO > 0, t.STOCK_NUEVO * t.PMP_NUEVO, 0),
           IF(t.STOCK_NUEVO > 0, t.PMP_NUEVO, 0),
           NOW()
      FROM tmp_movs_ord t
      JOIN (
            SELECT CODIGO_UNIDAD_MOV, MAX(RN) AS RN_MAX
              FROM tmp_movs_ord
             GROUP BY CODIGO_UNIDAD_MOV
           ) ult
        ON ult.CODIGO_UNIDAD_MOV = t.CODIGO_UNIDAD_MOV
       AND ult.RN_MAX             = t.RN
     ON DUPLICATE KEY UPDATE
        CANTIDAD_STK     = VALUES(CANTIDAD_STK),
        VALOR_TOTAL_STK  = VALUES(VALOR_TOTAL_STK),
        PRECIO_MEDIO_STK = VALUES(PRECIO_MEDIO_STK),
        INSTANTE_MODIF   = NOW();

    /* 5. SKUs sin movs sobrevivientes (todos sus movs estaban en la
       regularizacion borrada): el stockactual queda a 0. */
    INSERT INTO fza_articulos_stockactual
        (CODIGO_ALM_STK, CODIGO_UNIDAD_STK,
         CANTIDAD_STK, VALOR_TOTAL_STK, PRECIO_MEDIO_STK, INSTANTE_MODIF)
    SELECT p_ALMACEN, s.sku, 0, 0, 0, NOW()
      FROM tmp_skus_recalc s
      LEFT JOIN tmp_movs_ord t ON t.CODIGO_UNIDAD_MOV = s.sku
     WHERE t.CODIGO_UNIDAD_MOV IS NULL
     ON DUPLICATE KEY UPDATE
        CANTIDAD_STK     = 0,
        VALOR_TOTAL_STK  = 0,
        PRECIO_MEDIO_STK = 0,
        INSTANTE_MODIF   = NOW();

    DROP TEMPORARY TABLE IF EXISTS tmp_movs_ord;
END ;;
DELIMITER ;


-- -----------------------------------------------------------------------------
-- SP_RECALCULAR_PMP_SKU_ALMACEN (compat: misma firma, delega en el lote)
-- -----------------------------------------------------------------------------
-- Se mantiene por si algun futuro llamante espera la interfaz por SKU.
-- Hoy ningun .pas la usa directamente.
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `SP_RECALCULAR_PMP_SKU_ALMACEN`;
DELIMITER ;;
CREATE PROCEDURE `SP_RECALCULAR_PMP_SKU_ALMACEN`(
    IN p_CodigoEmpresa VARCHAR(20),
    IN p_CodigoSKU     VARCHAR(50),
    IN p_CodigoAlmacen VARCHAR(10)
)
BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;
    CREATE TEMPORARY TABLE tmp_skus_recalc (
        sku VARCHAR(50) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB;

    INSERT INTO tmp_skus_recalc (sku) VALUES (p_CodigoSKU);

    CALL SP_RECALCULAR_PMP_LOTE_ALMACEN(p_CodigoEmpresa, p_CodigoAlmacen);

    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;
END ;;
DELIMITER ;


-- -----------------------------------------------------------------------------
-- PRC_FZA_INVENTARIOS_ELIMINAR_REGUL (reescrito: una sola llamada al lote)
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_ELIMINAR_REGUL`;
DELIMITER ;;
CREATE PROCEDURE `PRC_FZA_INVENTARIOS_ELIMINAR_REGUL`(
    IN p_EMPRESA VARCHAR(10),
    IN p_ALMACEN VARCHAR(10),
    IN p_SERIE   VARCHAR(20),
    IN p_NRO     VARCHAR(20),
    IN p_USUARIO VARCHAR(100)
)
BEGIN
    DECLARE v_ESTADO VARCHAR(20);
    DECLARE v_PATRON VARCHAR(50);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    /* 1. Verificar estado del inventario (debe estar APLICADO). */
    SELECT ESTADO_INV INTO v_ESTADO
      FROM fza_inventarios
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO
       FOR UPDATE;

    IF v_ESTADO IS NULL THEN
        SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT =
            ''Error: el inventario no existe.'';
    END IF;

    IF v_ESTADO <> ''APLICADO'' THEN
        SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT =
            ''Error: el inventario debe estar APLICADO para eliminar la regularizacion.'';
    END IF;

    SET v_PATRON = CONCAT(''IV-'', p_NRO, ''-%'');

    /* 2. Recoger en una temp los SKUs afectados ANTES de borrar. La temp
       sirve de input a SP_RECALCULAR_PMP_LOTE_ALMACEN. */
    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;
    CREATE TEMPORARY TABLE tmp_skus_recalc (
        sku VARCHAR(50) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB;

    INSERT INTO tmp_skus_recalc (sku)
    SELECT DISTINCT CODIGO_UNIDAD_MOV
      FROM fza_movimientos_almacen
     WHERE CODIGO_ALM_MOV = p_ALMACEN
       AND NUMERO_MOV LIKE v_PATRON;

    /* 3. Borrar los movimientos generados por el inventario. NUMERO_MOV es
       la PK; el LIKE con prefijo constante permite al optimizador usar la
       PK directamente. El AND CODIGO_ALM_MOV se mantiene por seguridad (un
       inventario solo genera movs en su almacen). */
    DELETE FROM fza_movimientos_almacen
     WHERE CODIGO_ALM_MOV = p_ALMACEN
       AND NUMERO_MOV LIKE v_PATRON;

    /* 4. Recalcular PMP y stockactual de todos los SKUs afectados en
       UNA sola pasada. */
    CALL SP_RECALCULAR_PMP_LOTE_ALMACEN(p_EMPRESA, p_ALMACEN);

    /* 5. Marcar el inventario como ABIERTO de nuevo. */
    UPDATE fza_inventarios
       SET ESTADO_INV     = ''ABIERTO'',
           USUARIO_MODIF  = p_USUARIO,
           INSTANTE_MODIF = NOW()
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;

    COMMIT;
END ;;
DELIMITER ;


-- -----------------------------------------------------------------------------
-- PRC_FZA_INVENTARIOS_APLICAR (reescrito: una sola llamada al lote al final)
-- -----------------------------------------------------------------------------
-- Conserva el cursor sobre lineas del inventario para generar los
-- movimientos S/E (esa parte sigue siendo lineal en numero de lineas, no de
-- movimientos historicos, asi que no es el cuello de botella). Lo que se
-- elimina es la llamada a SP_RECALCULAR_PMP_SKU_ALMACEN dentro del bucle.
-- Tras insertar todos los movimientos, una unica llamada al lote recalcula
-- el PMP de todos los SKUs tocados.
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_APLICAR`;
DELIMITER ;;
CREATE PROCEDURE `PRC_FZA_INVENTARIOS_APLICAR`(
    IN p_EMPRESA VARCHAR(10),
    IN p_ALMACEN VARCHAR(10),
    IN p_SERIE   VARCHAR(20),
    IN p_NRO     VARCHAR(20),
    IN p_USUARIO VARCHAR(100)
)
BEGIN
    DECLARE v_DONE   INT DEFAULT FALSE;
    DECLARE v_ESTADO VARCHAR(20);
    DECLARE v_FECHA_CABECERA DATETIME;
    DECLARE v_FECHA_DEFECTO  DATETIME;

    DECLARE v_LINEA     VARCHAR(4);
    DECLARE v_ARTICULO  VARCHAR(20);
    DECLARE v_SKU       VARCHAR(50);
    DECLARE v_TEORICA   DECIMAL(19,6);
    DECLARE v_FISICA    DECIMAL(19,6);
    DECLARE v_PMP_HIST  DECIMAL(19,6);
    DECLARE v_PMP_NUEVO DECIMAL(19,6);
    DECLARE v_FECHA_RECUENTO DATETIME;
    DECLARE v_FECHA_SALIDA   DATETIME;

    DECLARE v_MOV_SALIDA  VARCHAR(20);
    DECLARE v_MOV_ENTRADA VARCHAR(20);

    DECLARE cur_lineas CURSOR FOR
        SELECT l.LINEA_INVLIN,
               l.CODIGO_ART_INVLIN,
               l.CODIGO_UNIDAD_INVLIN,
               l.CANTIDAD_TEORICA_INVLIN,
               l.CANTIDAD_FISICA_INVLIN,
               l.PRECIO_MEDIO_INVLIN,
               l.PRECIO_MEDIO_NUEVO_INVLIN,
               l.FECHA_RECUENTO_INVLIN
          FROM fza_inventarios_lineas l
         WHERE l.CODIGO_EMP_INVLIN = p_EMPRESA
           AND l.CODIGO_ALM_INVLIN = p_ALMACEN
           AND l.SERIE_INV_INVLIN  = p_SERIE
           AND l.NUMERO_INV_INVLIN = p_NRO;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_DONE = TRUE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    CALL PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO(
        p_EMPRESA, p_ALMACEN, p_SERIE, p_NRO, p_USUARIO
    );

    START TRANSACTION;

    SELECT ESTADO_INV, FECHA_INV
      INTO v_ESTADO, v_FECHA_CABECERA
      FROM fza_inventarios
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO
       FOR UPDATE;

    IF v_ESTADO != ''ABIERTO'' THEN
        SIGNAL SQLSTATE ''45000''
          SET MESSAGE_TEXT = ''Error: El inventario ya fue aplicado o esta cancelado.'';
    END IF;

    SET v_FECHA_DEFECTO = TIMESTAMP(DATE_SUB(DATE(v_FECHA_CABECERA), INTERVAL 1 DAY), ''23:59:59'');

    DELETE FROM fza_inventarios_lineas
     WHERE CODIGO_EMP_INVLIN              = p_EMPRESA
       AND CODIGO_ALM_INVLIN              = p_ALMACEN
       AND SERIE_INV_INVLIN               = p_SERIE
       AND NUMERO_INV_INVLIN              = p_NRO
       AND IFNULL(CANTIDAD_DIFERENCIA_INVLIN,    0) = 0
       AND IFNULL(TOTAL_COSTE_DIFERENCIA_INVLIN, 0) = 0;

    UPDATE fza_inventarios
       SET TOTAL_UNIDADES_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(CANTIDAD_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas
                WHERE CODIGO_EMP_INVLIN = p_EMPRESA
                  AND CODIGO_ALM_INVLIN = p_ALMACEN
                  AND SERIE_INV_INVLIN  = p_SERIE
                  AND NUMERO_INV_INVLIN = p_NRO
           ),
           TOTAL_EUROS_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(TOTAL_COSTE_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas
                WHERE CODIGO_EMP_INVLIN = p_EMPRESA
                  AND CODIGO_ALM_INVLIN = p_ALMACEN
                  AND SERIE_INV_INVLIN  = p_SERIE
                  AND NUMERO_INV_INVLIN = p_NRO
           )
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    /* Temp para recolectar los SKUs tocados durante la generacion de movs.
       Se rellena dentro del bucle y se consume al final con una sola
       llamada al recalculo en lote. */
    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;
    CREATE TEMPORARY TABLE tmp_skus_recalc (
        sku VARCHAR(50) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB;

    OPEN cur_lineas;

    read_loop: LOOP
        FETCH cur_lineas
         INTO v_LINEA, v_ARTICULO, v_SKU, v_TEORICA, v_FISICA, v_PMP_HIST, v_PMP_NUEVO, v_FECHA_RECUENTO;

        IF v_DONE THEN
            LEAVE read_loop;
        END IF;

        IF v_FECHA_RECUENTO IS NULL THEN
            SET v_FECHA_RECUENTO = v_FECHA_DEFECTO;
        END IF;

        SET v_FECHA_SALIDA = DATE_SUB(v_FECHA_RECUENTO, INTERVAL 1 SECOND);
        SET v_MOV_SALIDA  = LEFT(CONCAT(''IV-'', p_NRO, ''-'', v_LINEA, ''S''), 20);
        SET v_MOV_ENTRADA = LEFT(CONCAT(''IV-'', p_NRO, ''-'', v_LINEA, ''E''), 20);

        IF v_TEORICA <> 0 THEN
            CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT(
                v_MOV_SALIDA, ''IN'', p_SERIE, p_NRO, v_LINEA,
                p_EMPRESA, p_ALMACEN, NULL, v_SKU,
                ''S'', v_TEORICA, v_PMP_HIST, (v_TEORICA * v_PMP_HIST),
                p_USUARIO, p_ALMACEN, NULL, NULL, NULL, v_ARTICULO
            );
            UPDATE fza_movimientos_almacen
               SET FECHA_MOV = v_FECHA_SALIDA
             WHERE NUMERO_MOV = v_MOV_SALIDA;
        END IF;

        IF v_FISICA > 0 THEN
            CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT(
                v_MOV_ENTRADA, ''IN'', p_SERIE, p_NRO, v_LINEA,
                p_EMPRESA, p_ALMACEN, NULL, v_SKU,
                ''E'', v_FISICA, v_PMP_NUEVO, (v_FISICA * v_PMP_NUEVO),
                p_USUARIO, p_ALMACEN, NULL, NULL, NULL, v_ARTICULO
            );
            UPDATE fza_movimientos_almacen
               SET FECHA_MOV = v_FECHA_RECUENTO
             WHERE NUMERO_MOV = v_MOV_ENTRADA;
        END IF;

        /* Anotamos el SKU para el recalculo en lote. INSERT IGNORE evita
           duplicados si varias lineas tocan el mismo SKU. */
        INSERT IGNORE INTO tmp_skus_recalc (sku) VALUES (v_SKU);

    END LOOP;

    CLOSE cur_lineas;

    /* Recalculo set-based sobre todos los SKUs tocados. Reemplaza la
       llamada SP_RECALCULAR_PMP_SKU_ALMACEN por linea del cursor. */
    CALL SP_RECALCULAR_PMP_LOTE_ALMACEN(p_EMPRESA, p_ALMACEN);

    UPDATE fza_inventarios
       SET ESTADO_INV     = ''APLICADO'',
           USUARIO_MODIF  = p_USUARIO,
           INSTANTE_MODIF = NOW()
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;

    COMMIT;
END ;;
DELIMITER ;
', '2026-05-20 18:47:17', '2026-05-20 18:47:17', 'Administrador', 'Administrador'),
  ('233', 'optimizar_recalculo_pmp', '-- =============================================================================
-- Optimizar recalculo PMP en aplicar / eliminar regularizacion de inventario
-- =============================================================================
-- Sustituye el cursor anidado de SP_RECALCULAR_PMP_SKU_ALMACEN +
-- PRC_FZA_INVENTARIOS_ELIMINAR_REGUL + PRC_FZA_INVENTARIOS_APLICAR por una
-- pasada en conjunto (set-based) sobre todos los SKUs afectados.
--
-- Antes:
--   PRC_FZA_INVENTARIOS_ELIMINAR_REGUL recorre los SKUs afectados con cursor
--   y por cada uno llama a SP_RECALCULAR_PMP_SKU_ALMACEN, que a su vez abre
--   otro cursor y lanza N UPDATE individuales (uno por movimiento) +
--   1 INSERT...ON DUPLICATE en stockactual. Para 50 SKUs con 200 movs cada
--   uno son ~10.000 statements y otros tantos X-locks `FOR UPDATE`.
--
-- Despues:
--   SP_RECALCULAR_PMP_LOTE_ALMACEN procesa todos los SKUs registrados en una
--   tabla temporal `tmp_skus_recalc` con 4 statements grandes:
--     1) volcado ordenado a `tmp_movs_ord` (PK auto-incremental garantiza el
--        orden secuencial),
--     2) UPDATE en lote con variables de sesion para el PMP acumulado
--        (reset al cambiar de SKU),
--     3) UPDATE...JOIN para volcar PRECIO_MEDIO_MOV / TOTAL_COSTE_MOV,
--     4) INSERT...ON DUPLICATE KEY UPDATE en fza_articulos_stockactual desde
--        el ultimo movimiento de cada SKU.
--
-- SP_RECALCULAR_PMP_SKU_ALMACEN se conserva con la misma firma como wrapper
-- (algun llamante futuro podria seguir esperando esa interfaz; hoy solo lo
-- usan los dos PRC_FZA_INVENTARIOS_*, que pasan a llamar directamente al
-- lote, pero el wrapper sigue ahi por compatibilidad).
--
-- Comportamiento funcional identico al original:
--   - Misma formula de PMP (entrada con stock<=0: pmp=coste; entrada con
--     stock>0: media ponderada; salida: pmp invariable).
--   - Mismo TOTAL_COSTE_MOV (cant*coste en entradas, cant*pmp en salidas).
--   - Mismo stockactual final por SKU.
--   - SKUs cuyos movs se han borrado por completo quedan a 0 en stockactual.
--
-- Idempotente: solo recrea procedimientos. `DROP PROCEDURE IF EXISTS` antes
-- de cada `CREATE PROCEDURE`. No cambia esquema. Se puede ejecutar varias
-- veces sin efectos secundarios.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- SP_RECALCULAR_PMP_LOTE_ALMACEN
-- -----------------------------------------------------------------------------
-- Recalcula PMP y stockactual de todos los SKUs presentes en la tabla
-- temporal `tmp_skus_recalc(sku VARCHAR(50) PRIMARY KEY)`, que el llamante
-- debe crear y poblar antes de invocar este procedimiento.
--
-- El procedimiento no abre transaccion: respeta la transaccion del llamante
-- (PRC_FZA_INVENTARIOS_APLICAR / PRC_FZA_INVENTARIOS_ELIMINAR_REGUL ya la
-- abren).
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `SP_RECALCULAR_PMP_LOTE_ALMACEN`;
DELIMITER ;;
CREATE PROCEDURE `SP_RECALCULAR_PMP_LOTE_ALMACEN`(
    IN p_EMPRESA VARCHAR(20),
    IN p_ALMACEN VARCHAR(10)
)
BEGIN
    /* 1. Tabla con todos los movs de los SKUs afectados, ordenados.
       El INSERT...SELECT ORDER BY garantiza el orden de RN secuencial
       (RN es AUTO_INCREMENT como PK clustered en InnoDB). */
    DROP TEMPORARY TABLE IF EXISTS tmp_movs_ord;
    CREATE TEMPORARY TABLE tmp_movs_ord (
        RN                        BIGINT          NOT NULL AUTO_INCREMENT,
        NUMERO_MOV                VARCHAR(20)     NOT NULL,
        CODIGO_UNIDAD_MOV         VARCHAR(50)     NOT NULL,
        TIPO_MOV                  VARCHAR(1)      NOT NULL,
        CANTIDAD_MOV              DECIMAL(19,6)   NOT NULL,
        PRECIO_COSTE_UNITARIO_MOV DECIMAL(19,6)   NOT NULL,
        PMP_NUEVO                 DECIMAL(19,6)   NOT NULL DEFAULT 0,
        STOCK_NUEVO               DECIMAL(19,6)   NOT NULL DEFAULT 0,
        COSTE_NUEVO               DECIMAL(19,6)   NOT NULL DEFAULT 0,
        SKU_PREV                  VARCHAR(50)     NULL,
        PRIMARY KEY (RN),
        KEY IDX_NUMMOV (NUMERO_MOV),
        KEY IDX_SKU    (CODIGO_UNIDAD_MOV)
    ) ENGINE=InnoDB;

    INSERT INTO tmp_movs_ord
        (NUMERO_MOV, CODIGO_UNIDAD_MOV, TIPO_MOV, CANTIDAD_MOV,
         PRECIO_COSTE_UNITARIO_MOV)
    SELECT m.NUMERO_MOV,
           m.CODIGO_UNIDAD_MOV,
           m.TIPO_MOV,
           IFNULL(m.CANTIDAD_MOV, 0),
           IFNULL(m.PRECIO_COSTE_UNITARIO_MOV, 0)
      FROM fza_movimientos_almacen m
      JOIN tmp_skus_recalc s ON s.sku = m.CODIGO_UNIDAD_MOV
     WHERE m.CODIGO_ALM_MOV = p_ALMACEN
     ORDER BY m.CODIGO_UNIDAD_MOV, m.FECHA_MOV, m.INSTANTE_ALTA;

    /* 2. Calculo acumulado por SKU con variables de sesion. El ORDER BY RN
       fuerza el barrido secuencial por la PK clustered. Las asignaciones del
       SET se evaluan de izquierda a derecha: primero PMP_NUEVO (usa @stock y
       @pmp todavia con valor de la fila anterior + @sku_prev de la fila
       anterior para detectar cambio), luego COSTE_NUEVO (usa el @pmp recien
       calculado), luego STOCK_NUEVO (actualiza @stock), y al final SKU_PREV
       actualiza @sku_prev para la siguiente fila. */
    SET @sku_prev := '''';
    SET @stock    := 0;
    SET @pmp      := 0;

    UPDATE tmp_movs_ord
       SET PMP_NUEVO = (
               @pmp := IF(
                   @sku_prev <> CODIGO_UNIDAD_MOV,
                   /* Cambio de SKU: empezamos desde cero */
                   IF(TIPO_MOV = ''E'', PRECIO_COSTE_UNITARIO_MOV, 0),
                   /* Mismo SKU que la fila anterior */
                   IF(TIPO_MOV = ''E'',
                       IF(@stock <= 0,
                           PRECIO_COSTE_UNITARIO_MOV,
                           ((@stock * @pmp)
                              + (CANTIDAD_MOV * PRECIO_COSTE_UNITARIO_MOV))
                            / (@stock + CANTIDAD_MOV)),
                       @pmp
                   )
               )
           ),
           COSTE_NUEVO = IF(TIPO_MOV = ''E'',
                            CANTIDAD_MOV * PRECIO_COSTE_UNITARIO_MOV,
                            CANTIDAD_MOV * @pmp),
           STOCK_NUEVO = (
               @stock := IF(
                   @sku_prev <> CODIGO_UNIDAD_MOV,
                   /* Cambio de SKU: stock empieza en 0 y se suma este mov */
                   IF(TIPO_MOV = ''E'', CANTIDAD_MOV, -CANTIDAD_MOV),
                   IF(TIPO_MOV = ''E'', @stock + CANTIDAD_MOV,
                                       @stock - CANTIDAD_MOV)
               )
           ),
           SKU_PREV = (@sku_prev := CODIGO_UNIDAD_MOV)
     ORDER BY RN;

    /* 3. Volcado en lote a fza_movimientos_almacen. Un solo UPDATE...JOIN
       toma X-locks sobre los movs afectados y los libera al terminar. */
    UPDATE fza_movimientos_almacen m
      JOIN tmp_movs_ord t ON t.NUMERO_MOV = m.NUMERO_MOV
       SET m.PRECIO_MEDIO_MOV = t.PMP_NUEVO,
           m.TOTAL_COSTE_MOV  = t.COSTE_NUEVO;

    /* 4. Stock final por SKU: el ultimo mov (RN maximo) tiene el stock y
       el PMP acumulados al final del historico. Volcamos a stockactual. */
    INSERT INTO fza_articulos_stockactual
        (CODIGO_ALM_STK, CODIGO_UNIDAD_STK,
         CANTIDAD_STK, VALOR_TOTAL_STK, PRECIO_MEDIO_STK, INSTANTE_MODIF)
    SELECT p_ALMACEN,
           t.CODIGO_UNIDAD_MOV,
           t.STOCK_NUEVO,
           IF(t.STOCK_NUEVO > 0, t.STOCK_NUEVO * t.PMP_NUEVO, 0),
           IF(t.STOCK_NUEVO > 0, t.PMP_NUEVO, 0),
           NOW()
      FROM tmp_movs_ord t
      JOIN (
            SELECT CODIGO_UNIDAD_MOV, MAX(RN) AS RN_MAX
              FROM tmp_movs_ord
             GROUP BY CODIGO_UNIDAD_MOV
           ) ult
        ON ult.CODIGO_UNIDAD_MOV = t.CODIGO_UNIDAD_MOV
       AND ult.RN_MAX             = t.RN
     ON DUPLICATE KEY UPDATE
        CANTIDAD_STK     = VALUES(CANTIDAD_STK),
        VALOR_TOTAL_STK  = VALUES(VALOR_TOTAL_STK),
        PRECIO_MEDIO_STK = VALUES(PRECIO_MEDIO_STK),
        INSTANTE_MODIF   = NOW();

    /* 5. SKUs sin movs sobrevivientes (todos sus movs estaban en la
       regularizacion borrada): el stockactual queda a 0. */
    INSERT INTO fza_articulos_stockactual
        (CODIGO_ALM_STK, CODIGO_UNIDAD_STK,
         CANTIDAD_STK, VALOR_TOTAL_STK, PRECIO_MEDIO_STK, INSTANTE_MODIF)
    SELECT p_ALMACEN, s.sku, 0, 0, 0, NOW()
      FROM tmp_skus_recalc s
      LEFT JOIN tmp_movs_ord t ON t.CODIGO_UNIDAD_MOV = s.sku
     WHERE t.CODIGO_UNIDAD_MOV IS NULL
     ON DUPLICATE KEY UPDATE
        CANTIDAD_STK     = 0,
        VALOR_TOTAL_STK  = 0,
        PRECIO_MEDIO_STK = 0,
        INSTANTE_MODIF   = NOW();

    DROP TEMPORARY TABLE IF EXISTS tmp_movs_ord;
END ;;
DELIMITER ;


-- -----------------------------------------------------------------------------
-- SP_RECALCULAR_PMP_SKU_ALMACEN (compat: misma firma, delega en el lote)
-- -----------------------------------------------------------------------------
-- Se mantiene por si algun futuro llamante espera la interfaz por SKU.
-- Hoy ningun .pas la usa directamente.
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `SP_RECALCULAR_PMP_SKU_ALMACEN`;
DELIMITER ;;
CREATE PROCEDURE `SP_RECALCULAR_PMP_SKU_ALMACEN`(
    IN p_CodigoEmpresa VARCHAR(20),
    IN p_CodigoSKU     VARCHAR(50),
    IN p_CodigoAlmacen VARCHAR(10)
)
BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;
    CREATE TEMPORARY TABLE tmp_skus_recalc (
        sku VARCHAR(50) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB;

    INSERT INTO tmp_skus_recalc (sku) VALUES (p_CodigoSKU);

    CALL SP_RECALCULAR_PMP_LOTE_ALMACEN(p_CodigoEmpresa, p_CodigoAlmacen);

    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;
END ;;
DELIMITER ;


-- -----------------------------------------------------------------------------
-- PRC_FZA_INVENTARIOS_ELIMINAR_REGUL (reescrito: una sola llamada al lote)
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_ELIMINAR_REGUL`;
DELIMITER ;;
CREATE PROCEDURE `PRC_FZA_INVENTARIOS_ELIMINAR_REGUL`(
    IN p_EMPRESA VARCHAR(10),
    IN p_ALMACEN VARCHAR(10),
    IN p_SERIE   VARCHAR(20),
    IN p_NRO     VARCHAR(20),
    IN p_USUARIO VARCHAR(100)
)
BEGIN
    DECLARE v_ESTADO VARCHAR(20);
    DECLARE v_PATRON VARCHAR(50);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    /* 1. Verificar estado del inventario (debe estar APLICADO). */
    SELECT ESTADO_INV INTO v_ESTADO
      FROM fza_inventarios
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO
       FOR UPDATE;

    IF v_ESTADO IS NULL THEN
        SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT =
            ''Error: el inventario no existe.'';
    END IF;

    IF v_ESTADO <> ''APLICADO'' THEN
        SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT =
            ''Error: el inventario debe estar APLICADO para eliminar la regularizacion.'';
    END IF;

    SET v_PATRON = CONCAT(''IV-'', p_NRO, ''-%'');

    /* 2. Recoger en una temp los SKUs afectados ANTES de borrar. La temp
       sirve de input a SP_RECALCULAR_PMP_LOTE_ALMACEN. */
    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;
    CREATE TEMPORARY TABLE tmp_skus_recalc (
        sku VARCHAR(50) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB;

    INSERT INTO tmp_skus_recalc (sku)
    SELECT DISTINCT CODIGO_UNIDAD_MOV
      FROM fza_movimientos_almacen
     WHERE CODIGO_ALM_MOV = p_ALMACEN
       AND NUMERO_MOV LIKE v_PATRON;

    /* 3. Borrar los movimientos generados por el inventario. NUMERO_MOV es
       la PK; el LIKE con prefijo constante permite al optimizador usar la
       PK directamente. El AND CODIGO_ALM_MOV se mantiene por seguridad (un
       inventario solo genera movs en su almacen). */
    DELETE FROM fza_movimientos_almacen
     WHERE CODIGO_ALM_MOV = p_ALMACEN
       AND NUMERO_MOV LIKE v_PATRON;

    /* 4. Recalcular PMP y stockactual de todos los SKUs afectados en
       UNA sola pasada. */
    CALL SP_RECALCULAR_PMP_LOTE_ALMACEN(p_EMPRESA, p_ALMACEN);

    /* 5. Marcar el inventario como ABIERTO de nuevo. */
    UPDATE fza_inventarios
       SET ESTADO_INV     = ''ABIERTO'',
           USUARIO_MODIF  = p_USUARIO,
           INSTANTE_MODIF = NOW()
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;

    COMMIT;
END ;;
DELIMITER ;


-- -----------------------------------------------------------------------------
-- PRC_FZA_INVENTARIOS_APLICAR (reescrito: una sola llamada al lote al final)
-- -----------------------------------------------------------------------------
-- Conserva el cursor sobre lineas del inventario para generar los
-- movimientos S/E (esa parte sigue siendo lineal en numero de lineas, no de
-- movimientos historicos, asi que no es el cuello de botella). Lo que se
-- elimina es la llamada a SP_RECALCULAR_PMP_SKU_ALMACEN dentro del bucle.
-- Tras insertar todos los movimientos, una unica llamada al lote recalcula
-- el PMP de todos los SKUs tocados.
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `PRC_FZA_INVENTARIOS_APLICAR`;
DELIMITER ;;
CREATE PROCEDURE `PRC_FZA_INVENTARIOS_APLICAR`(
    IN p_EMPRESA VARCHAR(10),
    IN p_ALMACEN VARCHAR(10),
    IN p_SERIE   VARCHAR(20),
    IN p_NRO     VARCHAR(20),
    IN p_USUARIO VARCHAR(100)
)
BEGIN
    DECLARE v_DONE   INT DEFAULT FALSE;
    DECLARE v_ESTADO VARCHAR(20);
    DECLARE v_FECHA_CABECERA DATETIME;
    DECLARE v_FECHA_DEFECTO  DATETIME;

    /* fza_inventarios_lineas.LINEA_INVLIN es VARCHAR(8) (formato
       ''00000001''...). El SP original tenia VARCHAR(4) aqui, lo que
       provocaba "#22001 Data too long for column ''v_LINEA''" en el FETCH
       cuando el contador de linea pasaba de 9999. */
    DECLARE v_LINEA     VARCHAR(8);
    DECLARE v_ARTICULO  VARCHAR(20);
    DECLARE v_SKU       VARCHAR(50);
    DECLARE v_TEORICA   DECIMAL(19,6);
    DECLARE v_FISICA    DECIMAL(19,6);
    DECLARE v_PMP_HIST  DECIMAL(19,6);
    DECLARE v_PMP_NUEVO DECIMAL(19,6);
    DECLARE v_FECHA_RECUENTO DATETIME;
    DECLARE v_FECHA_SALIDA   DATETIME;

    DECLARE v_MOV_SALIDA  VARCHAR(20);
    DECLARE v_MOV_ENTRADA VARCHAR(20);

    DECLARE cur_lineas CURSOR FOR
        SELECT l.LINEA_INVLIN,
               l.CODIGO_ART_INVLIN,
               l.CODIGO_UNIDAD_INVLIN,
               l.CANTIDAD_TEORICA_INVLIN,
               l.CANTIDAD_FISICA_INVLIN,
               l.PRECIO_MEDIO_INVLIN,
               l.PRECIO_MEDIO_NUEVO_INVLIN,
               l.FECHA_RECUENTO_INVLIN
          FROM fza_inventarios_lineas l
         WHERE l.CODIGO_EMP_INVLIN = p_EMPRESA
           AND l.CODIGO_ALM_INVLIN = p_ALMACEN
           AND l.SERIE_INV_INVLIN  = p_SERIE
           AND l.NUMERO_INV_INVLIN = p_NRO;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_DONE = TRUE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    CALL PRC_FZA_INVENTARIOS_ACTUALIZAR_TEORICO(
        p_EMPRESA, p_ALMACEN, p_SERIE, p_NRO, p_USUARIO
    );

    START TRANSACTION;

    SELECT ESTADO_INV, FECHA_INV
      INTO v_ESTADO, v_FECHA_CABECERA
      FROM fza_inventarios
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO
       FOR UPDATE;

    IF v_ESTADO != ''ABIERTO'' THEN
        SIGNAL SQLSTATE ''45000''
          SET MESSAGE_TEXT = ''Error: El inventario ya fue aplicado o esta cancelado.'';
    END IF;

    SET v_FECHA_DEFECTO = TIMESTAMP(DATE_SUB(DATE(v_FECHA_CABECERA), INTERVAL 1 DAY), ''23:59:59'');

    DELETE FROM fza_inventarios_lineas
     WHERE CODIGO_EMP_INVLIN              = p_EMPRESA
       AND CODIGO_ALM_INVLIN              = p_ALMACEN
       AND SERIE_INV_INVLIN               = p_SERIE
       AND NUMERO_INV_INVLIN              = p_NRO
       AND IFNULL(CANTIDAD_DIFERENCIA_INVLIN,    0) = 0
       AND IFNULL(TOTAL_COSTE_DIFERENCIA_INVLIN, 0) = 0;

    UPDATE fza_inventarios
       SET TOTAL_UNIDADES_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(CANTIDAD_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas
                WHERE CODIGO_EMP_INVLIN = p_EMPRESA
                  AND CODIGO_ALM_INVLIN = p_ALMACEN
                  AND SERIE_INV_INVLIN  = p_SERIE
                  AND NUMERO_INV_INVLIN = p_NRO
           ),
           TOTAL_EUROS_DIFERENCIA_INV = (
               SELECT IFNULL(SUM(TOTAL_COSTE_DIFERENCIA_INVLIN), 0)
                 FROM fza_inventarios_lineas
                WHERE CODIGO_EMP_INVLIN = p_EMPRESA
                  AND CODIGO_ALM_INVLIN = p_ALMACEN
                  AND SERIE_INV_INVLIN  = p_SERIE
                  AND NUMERO_INV_INVLIN = p_NRO
           )
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    /* Temp para recolectar los SKUs tocados durante la generacion de movs.
       Se rellena dentro del bucle y se consume al final con una sola
       llamada al recalculo en lote. */
    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;
    CREATE TEMPORARY TABLE tmp_skus_recalc (
        sku VARCHAR(50) NOT NULL PRIMARY KEY
    ) ENGINE=InnoDB;

    OPEN cur_lineas;

    read_loop: LOOP
        FETCH cur_lineas
         INTO v_LINEA, v_ARTICULO, v_SKU, v_TEORICA, v_FISICA, v_PMP_HIST, v_PMP_NUEVO, v_FECHA_RECUENTO;

        IF v_DONE THEN
            LEAVE read_loop;
        END IF;

        IF v_FECHA_RECUENTO IS NULL THEN
            SET v_FECHA_RECUENTO = v_FECHA_DEFECTO;
        END IF;

        SET v_FECHA_SALIDA = DATE_SUB(v_FECHA_RECUENTO, INTERVAL 1 SECOND);
        SET v_MOV_SALIDA  = LEFT(CONCAT(''IV-'', p_NRO, ''-'', v_LINEA, ''S''), 20);
        SET v_MOV_ENTRADA = LEFT(CONCAT(''IV-'', p_NRO, ''-'', v_LINEA, ''E''), 20);

        IF v_TEORICA <> 0 THEN
            CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT(
                v_MOV_SALIDA, ''IN'', p_SERIE, p_NRO, v_LINEA,
                p_EMPRESA, p_ALMACEN, NULL, v_SKU,
                ''S'', v_TEORICA, v_PMP_HIST, (v_TEORICA * v_PMP_HIST),
                p_USUARIO, p_ALMACEN, NULL, NULL, NULL, v_ARTICULO
            );
            UPDATE fza_movimientos_almacen
               SET FECHA_MOV = v_FECHA_SALIDA
             WHERE NUMERO_MOV = v_MOV_SALIDA;
        END IF;

        IF v_FISICA > 0 THEN
            CALL PRC_FZA_MOVIMIENTOS_ALMACEN_INSERT(
                v_MOV_ENTRADA, ''IN'', p_SERIE, p_NRO, v_LINEA,
                p_EMPRESA, p_ALMACEN, NULL, v_SKU,
                ''E'', v_FISICA, v_PMP_NUEVO, (v_FISICA * v_PMP_NUEVO),
                p_USUARIO, p_ALMACEN, NULL, NULL, NULL, v_ARTICULO
            );
            UPDATE fza_movimientos_almacen
               SET FECHA_MOV = v_FECHA_RECUENTO
             WHERE NUMERO_MOV = v_MOV_ENTRADA;
        END IF;

        /* Anotamos el SKU para el recalculo en lote. INSERT IGNORE evita
           duplicados si varias lineas tocan el mismo SKU. */
        INSERT IGNORE INTO tmp_skus_recalc (sku) VALUES (v_SKU);

    END LOOP;

    CLOSE cur_lineas;

    /* Recalculo set-based sobre todos los SKUs tocados. Reemplaza la
       llamada SP_RECALCULAR_PMP_SKU_ALMACEN por linea del cursor. */
    CALL SP_RECALCULAR_PMP_LOTE_ALMACEN(p_EMPRESA, p_ALMACEN);

    UPDATE fza_inventarios
       SET ESTADO_INV     = ''APLICADO'',
           USUARIO_MODIF  = p_USUARIO,
           INSTANTE_MODIF = NOW()
     WHERE CODIGO_EMP_INV = p_EMPRESA
       AND CODIGO_ALM_INV = p_ALMACEN
       AND SERIE_INV      = p_SERIE
       AND NUMERO_INV     = p_NRO;

    DROP TEMPORARY TABLE IF EXISTS tmp_skus_recalc;

    COMMIT;
END ;;
DELIMITER ;
', '2026-05-20 18:57:44', '2026-05-20 18:57:44', 'Administrador', 'Administrador'),
  ('234', NULL, '-- 1) Plan de ejecucion: por que tarda 6s
EXPLAIN
SELECT *
FROM vi_articulos_tarifas
WHERE CODIGO_ART_ARTTAR = ''01010002'';', '2026-05-20 21:57:55', '2026-05-20 21:52:56', 'Administrador', 'Administrador'),
  ('235', 'vi_articulos_tarifas_optimizada', '-- ============================================================================
--  vi_articulos_tarifas — Version optimizada
-- ----------------------------------------------------------------------------
--  Problema:
--    La version original tardaba ~6 segundos en un filtro como
--    WHERE CODIGO_ART_ARTTAR = ''01010002''. El EXPLAIN revelaba tres cuellos:
--
--    1. DEPENDENT SUBQUERY TIENE_SKU      → 119 lookups por fila resultado
--    2. DEPENDENT SUBQUERY NUM_ATRIBUTOS_REQ → JOIN + GROUP por fila
--    3. CTE sku_desc materializado        → full scan av (3837 filas) +
--                                            Using temporary + Using filesort
--
--    Para 15 tarifas de un articulo, esto disparaba miles de operaciones
--    secundarias en cada apertura.
--
--  Cambios respecto al original:
--
--    A. CTE sku_desc eliminado. La descripcion del SKU se calcula con una
--       subquery escalar en el SELECT. Asi se evalua una vez por fila
--       resultado (~15) con indice por CODIGO_UNIDAD_SKU_SA, en lugar de
--       materializar todo el conjunto agrupado.
--
--    B. TIENE_SKU pasa a LEFT JOIN con sub-tabla derivada DISTINCT (un solo
--       paso por todos los artículos con SKU activo, vs N pasos individuales).
--
--    C. NUM_ATRIBUTOS_REQ pasa a LEFT JOIN agregado, calculado una sola vez
--       por articulo y reusable.
--
--    D. FECHA_HASTA_ARTTAR > = curdate() pasa a sargeable
--       (IS NULL OR >= curdate()) — usa indice si existe.
--
--  Resultado esperado: el WHERE en vi_articulos_tarifas debe pasar de ~6s
--  a < 200 ms tras crear los indices recomendados al final del script.
--
--  Idempotente: CREATE OR REPLACE VIEW + CREATE INDEX IF NOT EXISTS.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Reemplazo de la vista
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW vi_articulos_tarifas AS
SELECT
  at.CODIGO_ART_ARTTAR                        AS CODIGO_ART_ARTTAR,
  COALESCE(at.CODIGO_UNIDAD_ARTTAR, '''')       AS CODIGO_UNIDAD_ARTTAR,
  at.CODIGO_TAR_ARTTAR                        AS CODIGO_TAR_ARTTAR,
  t.NOMBRE_TAR_TAR                            AS NOMBRE_TAR_TAR,
  at.CODIGO_UNICO_ARTTAR                      AS CODIGO_UNICO_ARTTAR,
  CASE WHEN COALESCE(at.CODIGO_UNIDAD_ARTTAR,'''') <> ''''
       THEN at.CODIGO_UNICO_ARTTAR
       END                                    AS CODIGO_UNICO_TARIFA_SKU,
  CASE WHEN COALESCE(at.CODIGO_UNIDAD_ARTTAR,'''') = ''''
       THEN at.CODIGO_UNICO_ARTTAR
       END                                    AS CODIGO_UNICO_TARIFA_PADRE,
  CASE WHEN COALESCE(at.CODIGO_UNIDAD_ARTTAR,'''') <> ''''
       THEN ''ESPECIFICO_SKU''
       ELSE ''PADRE''
       END                                    AS ORIGEN_PRECIO,
  at.PRECIO_SALIDA_ARTTAR                     AS PRECIO_SALIDA_ARTTAR,
  at.PRECIO_FINAL_ARTTAR                      AS PRECIO_FINAL_ARTTAR,
  at.PRECIO_DTO_ARTTAR                        AS PRECIO_DTO_ARTTAR,
  at.PORCENTAJE_DTO_ARTTAR                    AS PORCENTAJE_DTO_ARTTAR,
  at.PORCENTAJE_MARGEN_ARTTAR                 AS PORCENTAJE_MARGEN_ARTTAR,
  at.VALOR_MULTIPLO_AJUSTE_ARTTAR             AS VALOR_MULTIPLO_AJUSTE_ARTTAR,
  at.VALOR_MENOS_AJUSTE_ARTTAR                AS VALOR_MENOS_AJUSTE_ARTTAR,
  COALESCE(at.PORCENTAJE_MARGEN_ARTTAR,
           t.PORCENTAJE_MARGEN_TAR)            AS PORCENTAJE_MARGEN_EFECTIVO,
  COALESCE(at.VALOR_MULTIPLO_AJUSTE_ARTTAR,
           t.VALOR_MULTIPLO_AJUSTE_TAR)        AS VALOR_MULTIPLO_AJUSTE_EFECTIVO,
  COALESCE(at.VALOR_MENOS_AJUSTE_ARTTAR,
           t.VALOR_MENOS_AJUSTE_TAR)           AS VALOR_MENOS_AJUSTE_EFECTIVO,
  at.FECHA_DESDE_ARTTAR                       AS FECHA_DESDE_ARTTAR,
  at.FECHA_HASTA_ARTTAR                       AS FECHA_HASTA_ARTTAR,
  t.ESACTIVO_ARTTAR                           AS ESACTIVO_ARTTAR,
  t.ESIMP_INCL_TAR                            AS ESIMP_INCL_TAR,
  t.ESDEFAULT_TAR                             AS ESDEFAULT_TAR,
  a.DESCRIPCION_ART                           AS DESCRIPCION_ART,
  a.TIPO_CANTIDAD_ART                         AS TIPO_CANTIDAD_ART,
  a.ESVARIACION_ART                           AS ESVARIACION_ART,
  iv.CODIGO_ABREVIATURA_IVA_IVATIP            AS TIPO_IVA_ARTICULO,
  -- (B) TIENE_SKU: antes DEPENDENT SUBQUERY; ahora LEFT JOIN DISTINCT.
  CASE WHEN tiene_sku.CODIGO_ART_SKU IS NOT NULL
       THEN ''S'' ELSE ''N''
       END                                    AS TIENE_SKU,
  sku.ESACTIVO_SKU                            AS ESACTIVO_SKU,
  -- (A) DESCRIPCION_SKU: antes CTE sku_desc materializado;
  -- ahora subquery escalar (15 ejecuciones con indice vs 1 full-scan + filesort).
  (SELECT GROUP_CONCAT(av.AV
                       ORDER BY av.ORDEN_AV ASC
                       SEPARATOR '' / '')
   FROM fza_atributos_sku sa
   JOIN fza_atributos_valores av ON av.ID_AV = sa.ID_AV_SA
   WHERE sa.CODIGO_UNIDAD_SKU_SA = at.CODIGO_UNIDAD_ARTTAR
  )                                            AS DESCRIPCION_SKU,
  ap.CODIGO_PRV_AP                             AS CODIGO_PRV_PRV,
  p.RAZON_SOCIAL_PRV                           AS RAZON_SOCIAL_PRV,
  CASE WHEN COALESCE(at.CODIGO_UNIDAD_ARTTAR,'''') <> ''''
       THEN skuc.PRECIO_ULT_COMPRA_SKUC
       ELSE ap.PRECIO_ULT_COMPRA_AP
       END                                    AS PRECIO_ULT_COMPRA,
  CASE WHEN COALESCE(at.CODIGO_UNIDAD_ARTTAR,'''') <> ''''
       THEN skuc.FECHA_ULT_COMPRA_SKUC
       ELSE ap.FECHA_VALIDEZ_AP
       END                                    AS FECHA_VALIDEZ,
  a.CODIGO_FAM_ART                            AS CODIGO_FAM_ART,
  af.DESCRIPCION_FAM                          AS DESCRIPCION_FAM,
  -- (C) NUM_ATRIBUTOS_REQ: antes DEPENDENT SUBQUERY con JOIN + GROUP por fila;
  -- ahora LEFT JOIN agregado precalculado por articulo.
  COALESCE(num_atr.NUM_ATRIBUTOS_REQ, 0)      AS NUM_ATRIBUTOS_REQ,
  at.INSTANTE_MODIF                           AS INSTANTE_MODIF,
  at.INSTANTE_ALTA                            AS INSTANTE_ALTA,
  at.USUARIO_ALTA                             AS USUARIO_ALTA,
  at.USUARIO_MODIF                            AS USUARIO_MODIF
FROM fza_articulos_tarifas at
  JOIN fza_articulos a ON a.CODIGO_ART_ART = at.CODIGO_ART_ARTTAR
  JOIN fza_tarifas    t ON t.CODIGO_TAR_ARTTAR = at.CODIGO_TAR_ARTTAR
  LEFT JOIN fza_articulos_skus sku
         ON sku.CODIGO_UNIDAD_SKU = at.CODIGO_UNIDAD_ARTTAR
        AND COALESCE(at.CODIGO_UNIDAD_ARTTAR,'''') <> ''''
  LEFT JOIN fza_articulos_skus_costes skuc
         ON skuc.CODIGO_UNIDAD_SKU_SKUC = at.CODIGO_UNIDAD_ARTTAR
        AND COALESCE(at.CODIGO_UNIDAD_ARTTAR,'''') <> ''''
  LEFT JOIN fza_articulos_proveedores ap
         ON ap.CODIGO_ART_AP = a.CODIGO_ART_ART
        AND ap.ESPROVEEDORPRINCIPAL_AP = ''S''
  LEFT JOIN fza_proveedores p
         ON p.CODIGO_PRV_PRV = ap.CODIGO_PRV_AP
  LEFT JOIN fza_articulos_familias af
         ON af.CODIGO_FAM_FAM = a.CODIGO_FAM_ART
  LEFT JOIN fza_ivas_tipos iv
         ON iv.CODIGO_ABREVIATURA_IVA_IVATIP = a.TIPO_IVA_ART
  -- (B) Sub-tabla DISTINCT de articulos con al menos un SKU activo.
  LEFT JOIN (
    SELECT DISTINCT CODIGO_ART_SKU
    FROM fza_articulos_skus
    WHERE ESACTIVO_SKU = ''S''
  ) tiene_sku ON tiene_sku.CODIGO_ART_SKU = a.CODIGO_ART_ART
  -- (C) Sub-tabla agregada con el numero de atributos requeridos por articulo.
  LEFT JOIN (
    SELECT sk.CODIGO_ART_SKU,
           COUNT(DISTINCT va.ID_ATB_VA) AS NUM_ATRIBUTOS_REQ
    FROM fza_articulos_skus sk
    JOIN fza_variaciones_atributos va ON va.ID_VAR_VA = sk.CODIGO_VAR_SKU
    GROUP BY sk.CODIGO_ART_SKU
  ) num_atr ON num_atr.CODIGO_ART_SKU = a.CODIGO_ART_ART
WHERE at.ESACTIVO_ARTTAR = ''S''
  AND t.ESACTIVO_ARTTAR = ''S''
  -- (D) Sargeable: usa indice sobre FECHA_HASTA_ARTTAR si existe.
  AND (at.FECHA_HASTA_ARTTAR IS NULL OR at.FECHA_HASTA_ARTTAR >= CURDATE())
ORDER BY t.ORDEN_TAR, a.ORDEN_ART, at.CODIGO_UNIDAD_ARTTAR;

-- ---------------------------------------------------------------------------
-- 2. Indices auxiliares (idempotentes — solo se crean si no existen)
--    MariaDB acepta CREATE INDEX IF NOT EXISTS desde 10.5.
-- ---------------------------------------------------------------------------

-- Para el WHERE sargeable de FECHA_HASTA_ARTTAR + ESACTIVO_ARTTAR:
CREATE INDEX IF NOT EXISTS IDX_ARTTAR_VIGENCIA
  ON fza_articulos_tarifas (ESACTIVO_ARTTAR, FECHA_HASTA_ARTTAR);

-- Para la subquery escalar DESCRIPCION_SKU sobre fza_atributos_sku:
-- el indice por CODIGO_UNIDAD_SKU_SA suele existir, pero por si acaso.
CREATE INDEX IF NOT EXISTS IDX_SA_UNIDAD
  ON fza_atributos_sku (CODIGO_UNIDAD_SKU_SA);

-- Para los LEFT JOIN tiene_sku / num_atr sobre fza_articulos_skus:
-- ya hay IDX_SKU_ART_ACT segun el EXPLAIN — no se crea de nuevo.

-- ---------------------------------------------------------------------------
-- 3. Verificacion manual (no se ejecuta automaticamente)
-- ---------------------------------------------------------------------------
-- Tras aplicar el script, comparar el plan antes/despues:
--
--   EXPLAIN SELECT * FROM vi_articulos_tarifas
--   WHERE CODIGO_ART_ARTTAR = ''01010002'';
--
-- Lo esperado:
--   - Ya no aparecen filas con select_type = DEPENDENT SUBQUERY.
--   - El DERIVED del CTE sku_desc desaparece.
--   - tiene_sku y num_atr aparecen como DERIVED (con id distinto al PRIMARY)
--     pero MariaDB los puede materializar en hash join eficiente.
--   - rows totales estimadas en miles, no en cientos de miles.
--
-- Y medir tiempos reales con:
--
--   ANALYZE FORMAT=JSON SELECT * FROM vi_articulos_tarifas
--   WHERE CODIGO_ART_ARTTAR = ''01010002'';
', '2026-05-20 22:29:32', '2026-05-20 22:29:32', 'Administrador', 'Administrador'),
  ('236', 'optimizar_caja_stock_pivotado', '-- =============================================================================
-- Optimizar PRC_GET_CAJA_STOCK_PIVOTADO y PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ
-- =============================================================================
-- Estos SPs reciben un input (codigo de articulo o SKU) y devuelven el stock
-- pivotado (almacenes en filas, tallas en columnas) para la pantalla de caja.
--
-- Antes (medido en sesion real, ConsultarStock SP=627 ms):
--   El SP hacia 6 sub-queries antes del PREPARE de la query final:
--     1. SELECT CODIGO_ART_ART FROM fza_articulos WHERE = p_input
--     2. (Si NULL) SELECT CODIGO_ART_SKU FROM fza_articulos_skus WHERE = p_input
--     3. SELECT pivot via 4 JOINs (sk -> ask -> av -> va) ORDER BY ORDEN_VA DESC
--     4. SELECT grupo/fila via 4 JOINs (idem) ORDER BY ORDEN_VA <DIR>
--     5. (Si SKU) SELECT valor del grupo (2 JOINs)
--     6. SELECT GROUP_CONCAT de columnas dinamicas (3 JOINs)
--   La query final pivotada en si ejecutaba en <1 ms (medido con
--   ANALYZE FORMAT=JSON: r_total_time_ms = 0.327). Los 627 ms se iban
--   enteros en las queries previas + overhead PREPARE.
--
-- Despues (estimado 150-250 ms):
--   - 1+2 combinadas en COALESCE: 1 round-trip en lugar de 2.
--   - 3 reescrita usando fza_articulos.TIPO_VARIACION_ART + fza_variaciones_atributos:
--     PK seek + index seek por TIPO_VARIACION_ART (ya tiene indice). El
--     resultado es identico para articulos con variacion bien definida —
--     mismo principio que aplicamos en ActualizarColumnasDinamicas (bajado
--     de 9.6 s a 14 ms).
--   - 4 idem reescrita.
--   - 5 sin cambios (2 JOINs filtrados por PK del SKU, ya es rapida).
--   - 6 sin cambios (necesita los AV reales de los SKUs, no del catalogo).
--
-- Importante: NO TOCAMOS la query final pivotada — el plan es correcto y
-- ejecuta en sub-milisegundo segun ANALYZE.
--
-- Idempotente: usa DROP PROCEDURE IF EXISTS + CREATE PROCEDURE. Re-aplicar
-- el script no rompe nada — sobreescribe los SPs con la version optimizada.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- PRC_GET_CAJA_STOCK_PIVOTADO
--   Devuelve el stock solo de los almacenes que tienen alguna fila para el
--   articulo. Es la version "compacta" usada en inMtoCajaOpe.qryStock.
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `PRC_GET_CAJA_STOCK_PIVOTADO`;
DELIMITER ;;
CREATE PROCEDURE `PRC_GET_CAJA_STOCK_PIVOTADO`(IN p_input VARCHAR(50))
BEGIN
    DECLARE v_codigo_articulo VARCHAR(20);
    DECLARE v_es_sku BOOLEAN DEFAULT FALSE;

    /* Variables para identificar que es Talla (Pivot) y que es Color (Grupo) */
    DECLARE v_id_atributo_pivot VARCHAR(20);  /* Ej: TAL */
    DECLARE v_id_atributo_grupo VARCHAR(20);  /* Ej: CO */

    /* Variable para filtrar si entramos con un SKU especifico (Ej: NEGRO) */
    DECLARE v_valor_grupo_filtro VARCHAR(50) DEFAULT NULL;

    DECLARE v_columnas_dinamicas TEXT;

    /* 1. RESOLUCION DE IDENTIDAD (¿Es Padre o SKU?)
       Antes: 2 sub-queries secuenciales (~100ms cada una con overhead SP).
       Ahora: COALESCE en una sola sentencia. PK seek en fza_articulos
       primero (el caso comun); si devuelve NULL, PK seek en
       fza_articulos_skus. El optimizador evalua el segundo SELECT solo
       cuando el primero da NULL.
       Si el resultado difiere del input literal, era un SKU. */
    SELECT COALESCE(
        (SELECT CODIGO_ART_ART
           FROM fza_articulos
          WHERE CODIGO_ART_ART = p_input
          LIMIT 1),
        (SELECT CODIGO_ART_SKU
           FROM fza_articulos_skus
          WHERE CODIGO_UNIDAD_SKU = p_input
          LIMIT 1)
    ) INTO v_codigo_articulo;

    IF v_codigo_articulo IS NOT NULL AND v_codigo_articulo <> p_input THEN
        SET v_es_sku = TRUE;
    END IF;

    /* 2. ESTRATEGIA DE ATRIBUTOS
       Antes: SET v_id_atributo_pivot = (SELECT ... 4-way JOIN sk -> ask -> av -> va
              WHERE sk.CODIGO_ART_SKU = v_codigo_articulo ORDER BY va.ORDEN_VA DESC LIMIT 1)
              + idem para el grupo. 2 round-trips, 8 JOINs en total.
       Ahora: PK seek sobre fza_articulos para sacar TIPO_VARIACION_ART, y
              index seek sobre fza_variaciones_atributos. Los atributos de
              la variacion estan definidos ahi, no hace falta recorrer SKUs.
              Mismo cambio que metimos en ActualizarColumnasDinamicas. */
    IF v_codigo_articulo IS NOT NULL THEN
        SELECT vat.ID_ATB_VA
          INTO v_id_atributo_pivot
          FROM fza_articulos art
          JOIN fza_variaciones_atributos vat
            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART
         WHERE art.CODIGO_ART_ART = v_codigo_articulo
         ORDER BY vat.ORDEN_VA DESC
         LIMIT 1;

        SELECT vat.ID_ATB_VA
          INTO v_id_atributo_grupo
          FROM fza_articulos art
          JOIN fza_variaciones_atributos vat
            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART
         WHERE art.CODIGO_ART_ART = v_codigo_articulo
           AND vat.ID_ATB_VA <> COALESCE(v_id_atributo_pivot, '''')
         ORDER BY vat.ORDEN_VA DESC
         LIMIT 1;
    END IF;

    /* 3. SI TENEMOS ESTRUCTURA PARA PIVOTAR... */
    IF v_id_atributo_pivot IS NOT NULL THEN

        /* 3.1 Si es SKU, detectamos el valor del atributo "Grupo".
           Sin cambios — 2 JOINs filtrados por PK del SKU. */
        IF v_es_sku = TRUE AND v_id_atributo_grupo IS NOT NULL THEN
            SET v_valor_grupo_filtro = (
                SELECT av.AV
                  FROM fza_atributos_sku ask
                  JOIN fza_atributos_valores av ON ask.ID_AV_SA = av.ID_AV
                 WHERE ask.CODIGO_UNIDAD_SKU_SA = p_input
                   AND av.ID_VA_AV = v_id_atributo_grupo
                 LIMIT 1
            );
        END IF;

        /* 3.2 Construir columnas dinamicas (S, M, L...).
           Sin cambios — necesitamos los AV REALES presentes en los SKUs del
           articulo, no los del catalogo (un articulo puede no usar todas las
           tallas posibles). Filtrado por CODIGO_ART_SKU (IDX_SKU_ART_ACT) y
           ID_VA_AV (IDX_VAR_AV). */
        SELECT GROUP_CONCAT(DISTINCT
            CONCAT(
                ''SUM(CASE WHEN av_p.AV = '''''', REPLACE(av.AV, '''''''', ''''''''''''),
                '''''' THEN stk.CANTIDAD_STK ELSE 0 END) AS `'', REPLACE(av.AV, ''`'', ''``''), ''`''
            )
            ORDER BY av.ID_AV
        ) INTO v_columnas_dinamicas
        FROM fza_articulos_skus sk
        JOIN fza_atributos_sku ask ON sk.CODIGO_UNIDAD_SKU = ask.CODIGO_UNIDAD_SKU_SA
        JOIN fza_atributos_valores av ON ask.ID_AV_SA = av.ID_AV
        WHERE sk.CODIGO_ART_SKU = v_codigo_articulo
          AND av.ID_VA_AV = v_id_atributo_pivot;

        /* 3.3 Construir Query Final — sin cambios. */
        IF v_columnas_dinamicas IS NOT NULL THEN
            SET @sql = CONCAT(
                ''SELECT
                    CONCAT('''''', v_codigo_articulo, '''''',
                        CASE
                            WHEN av_g.AV IS NOT NULL THEN CONCAT(''''/'''', av_g.AV)
                            ELSE ''''''''
                        END
                    ) AS Codigo,
                    alm.NOMBRE_ALM_ALM AS Almacen, '',
                    v_columnas_dinamicas, '',
                    SUM(stk.CANTIDAD_STK) AS Total
                 FROM fza_articulos_stockactual stk
                 JOIN fza_almacenes alm ON stk.CODIGO_ALM_STK = alm.CODIGO_ALM_ALM
                 JOIN fza_articulos_skus sk ON stk.CODIGO_UNIDAD_STK = sk.CODIGO_UNIDAD_SKU

                 JOIN fza_atributos_sku ask_p ON sk.CODIGO_UNIDAD_SKU = ask_p.CODIGO_UNIDAD_SKU_SA
                 JOIN fza_atributos_valores av_p ON ask_p.ID_AV_SA = av_p.ID_AV
                    AND av_p.ID_VA_AV = '''''', v_id_atributo_pivot, ''''''

                 LEFT JOIN fza_atributos_sku ask_g ON sk.CODIGO_UNIDAD_SKU = ask_g.CODIGO_UNIDAD_SKU_SA
                 LEFT JOIN fza_atributos_valores av_g ON ask_g.ID_AV_SA = av_g.ID_AV
                    AND av_g.ID_VA_AV = '''''', IFNULL(v_id_atributo_grupo, ''xxx''), ''''''

                 WHERE sk.CODIGO_ART_SKU = '''''', v_codigo_articulo, ''''''
                 '',
                 CASE WHEN v_valor_grupo_filtro IS NOT NULL THEN
                    CONCAT('' AND av_g.AV = '''''', REPLACE(v_valor_grupo_filtro, '''''''', ''''''''''''), '''''' '')
                 ELSE '''' END, ''

                 GROUP BY av_g.AV, alm.NOMBRE_ALM_ALM
                 ORDER BY alm.NOMBRE_ALM_ALM, av_g.AV''
            );

            PREPARE stmt FROM @sql;
            EXECUTE stmt;
            DEALLOCATE PREPARE stmt;

        END IF;
    END IF;

    /* CASO B: FALLBACK (Si no tiene atributos complejos o falla el pivotado) */
    IF v_columnas_dinamicas IS NULL THEN
        SELECT stk.CODIGO_UNIDAD_STK as Codigo,
            alm.NOMBRE_ALM_ALM as Almacen,
            SUM(stk.CANTIDAD_STK) as Stock_Total
        FROM fza_articulos_stockactual stk
        JOIN fza_almacenes alm ON stk.CODIGO_ALM_STK = alm.CODIGO_ALM_ALM
        WHERE stk.CODIGO_UNIDAD_STK = p_input
        GROUP BY stk.CODIGO_UNIDAD_STK, alm.NOMBRE_ALM_ALM
        ORDER BY alm.NOMBRE_ALM_ALM;
    END IF;

END ;;
DELIMITER ;


-- -----------------------------------------------------------------------------
-- PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ
--   Misma logica pero la query final arranca desde fza_almacenes con LEFT
--   JOIN: muestra TODOS los almacenes activos aunque tengan cero stock.
-- -----------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ`;
DELIMITER ;;
CREATE PROCEDURE `PRC_GET_CAJA_STOCK_PIVOTADO_WITHZ`(IN p_input VARCHAR(50))
BEGIN
    DECLARE v_codigo_articulo VARCHAR(20);
    DECLARE v_es_sku BOOLEAN DEFAULT FALSE;

    /* Variables para las COLUMNAS (Pivot - Ej: Talla) */
    DECLARE v_id_atributo_pivot VARCHAR(20);
    DECLARE v_nombre_atributo_pivot VARCHAR(50);
    DECLARE v_columnas_dinamicas TEXT;

    /* Variables para las FILAS (Desglose - Ej: Color) */
    DECLARE v_id_atributo_fila VARCHAR(20) DEFAULT NULL;
    DECLARE v_nombre_atributo_fila VARCHAR(50) DEFAULT NULL;
    DECLARE v_select_fila TEXT DEFAULT '''';
    DECLARE v_join_fila TEXT DEFAULT '''';
    DECLARE v_groupby_fila TEXT DEFAULT '''';
    DECLARE v_src_select_fila TEXT DEFAULT '''';

    DECLARE v_filtros_fijos TEXT DEFAULT '''';
    DECLARE v_sql_query TEXT;

    /* 1. IDENTIFICAR ARTICULO O SKU — COALESCE en una sola sentencia. */
    SELECT COALESCE(
        (SELECT CODIGO_ART_ART
           FROM fza_articulos
          WHERE CODIGO_ART_ART = p_input
          LIMIT 1),
        (SELECT CODIGO_ART_SKU
           FROM fza_articulos_skus
          WHERE CODIGO_UNIDAD_SKU = p_input
          LIMIT 1)
    ) INTO v_codigo_articulo;

    IF v_codigo_articulo IS NOT NULL AND v_codigo_articulo <> p_input THEN
        SET v_es_sku = TRUE;
    END IF;

    /* 2. BUSCAR ATRIBUTO PIVOTE (Para las columnas).
       Optimizado: via TIPO_VARIACION_ART (PK seek + index seek). */
    IF v_codigo_articulo IS NOT NULL THEN
        SELECT vat.ID_ATB_VA, vat.NOMBRE_VA
          INTO v_id_atributo_pivot, v_nombre_atributo_pivot
          FROM fza_articulos art
          JOIN fza_variaciones_atributos vat
            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART
         WHERE art.CODIGO_ART_ART = v_codigo_articulo
         ORDER BY vat.ORDEN_VA DESC
         LIMIT 1;
    END IF;

    /* 2.1 BUSCAR ATRIBUTO DE FILA (Ej: Color) SI ES UN ARTICULO GENERICO.
       Mantenemos ORDER BY ORDEN_VA ASC (la semantica original del SP _WITHZ
       difiere del PIVOTADO sin Z, que usaba DESC excluyendo el pivot).
       Para variaciones de 2 atributos da el mismo resultado. */
    IF v_codigo_articulo IS NOT NULL AND v_es_sku = FALSE THEN
        SELECT vat.ID_ATB_VA, vat.NOMBRE_VA
          INTO v_id_atributo_fila, v_nombre_atributo_fila
          FROM fza_articulos art
          JOIN fza_variaciones_atributos vat
            ON vat.ID_VAR_VA = art.TIPO_VARIACION_ART
         WHERE art.CODIGO_ART_ART = v_codigo_articulo
           AND vat.ID_ATB_VA <> v_id_atributo_pivot
         ORDER BY vat.ORDEN_VA ASC
         LIMIT 1;
    END IF;

    /* 3. CONSTRUCCION DE LA CONSULTA */
    IF v_id_atributo_pivot IS NOT NULL THEN

        /* Preparamos los textos dinamicos para desglosar el Color en filas */
        IF v_id_atributo_fila IS NOT NULL THEN
            SET v_select_fila = CONCAT('', COALESCE(src.VALOR_FILA, ''''-'''') AS `'', v_nombre_atributo_fila, ''`'');
            SET v_src_select_fila = '', av_fila.AV AS VALOR_FILA'';
            SET v_join_fila = CONCAT('' LEFT JOIN fza_atributos_sku ask_fila ON sk.CODIGO_UNIDAD_SKU = ask_fila.CODIGO_UNIDAD_SKU_SA LEFT JOIN fza_atributos_valores av_fila ON ask_fila.ID_AV_SA = av_fila.ID_AV AND av_fila.ID_VA_AV = '''''', v_id_atributo_fila, '''''' '');
            SET v_groupby_fila = '', src.VALOR_FILA'';
        END IF;

        /* Generamos columnas dinamicas apuntando a la subconsulta ''src''.
           Sin cambios — necesita los AV reales de los SKUs. */
        SELECT GROUP_CONCAT(DISTINCT
            CONCAT(
                ''SUM(CASE WHEN src.AV = '''''', av.AV,
                '''''' THEN src.CANTIDAD_STK ELSE 0 END) AS `'', av.AV, ''`''
            )
            ORDER BY av.ID_AV
        ) INTO v_columnas_dinamicas
        FROM fza_articulos_skus sk
        JOIN fza_atributos_sku ask ON sk.CODIGO_UNIDAD_SKU = ask.CODIGO_UNIDAD_SKU_SA
        JOIN fza_atributos_valores av ON ask.ID_AV_SA = av.ID_AV
        WHERE sk.CODIGO_ART_SKU = v_codigo_articulo
          AND av.ID_VA_AV = v_id_atributo_pivot;

        /* Filtros SKU (Solo aplica si buscas un SKU especifico) */
        IF v_es_sku = TRUE THEN
            SELECT GROUP_CONCAT(
                CONCAT(
                    '' AND EXISTS (SELECT 1 FROM fza_atributos_sku f_ask '',
                    '' JOIN fza_atributos_valores f_av ON f_ask.ID_AV_SA = f_av.ID_AV '',
                    '' WHERE f_ask.CODIGO_UNIDAD_SKU_SA = sk.CODIGO_UNIDAD_SKU '',
                    '' AND f_av.ID_VA_AV = '''''', av.ID_VA_AV, '''''' '',
                    '' AND f_av.AV = '''''', av.AV, '''''') ''
                ) SEPARATOR '' ''
            ) INTO v_filtros_fijos
            FROM fza_atributos_sku ask
            JOIN fza_atributos_valores av ON ask.ID_AV_SA = av.ID_AV
            WHERE ask.CODIGO_UNIDAD_SKU_SA = p_input
              AND av.ID_VA_AV <> v_id_atributo_pivot;
        END IF;

        IF v_filtros_fijos IS NULL THEN SET v_filtros_fijos = ''''; END IF;

        /* QUERY FINAL: Almacen + Atributo Fila (Color) + Columnas Dinamicas (Talla) */
        SET @sql = CONCAT(
            ''SELECT
                alm.NOMBRE_ALM_ALM AS Almacen'',
                v_select_fila, '', '',
                v_columnas_dinamicas, '',
                COALESCE(SUM(src.CANTIDAD_STK), 0) AS Total
             FROM fza_almacenes alm
             LEFT JOIN (
                SELECT stk.CODIGO_ALM_STK, av.AV, stk.CANTIDAD_STK'', v_src_select_fila, ''
                FROM fza_articulos_stockactual stk
                JOIN fza_articulos_skus sk ON stk.CODIGO_UNIDAD_STK = sk.CODIGO_UNIDAD_SKU
                JOIN fza_atributos_sku ask ON sk.CODIGO_UNIDAD_SKU = ask.CODIGO_UNIDAD_SKU_SA
                JOIN fza_atributos_valores av ON ask.ID_AV_SA = av.ID_AV'',
                v_join_fila, ''
                WHERE sk.CODIGO_ART_SKU = '''''', v_codigo_articulo, ''''''
                  AND av.ID_VA_AV = '''''', v_id_atributo_pivot, '''''' '',
                  v_filtros_fijos, ''
             ) src ON alm.CODIGO_ALM_ALM = src.CODIGO_ALM_STK
             WHERE alm.ESACTIVO_ALM = ''''S''''
             GROUP BY alm.NOMBRE_ALM_ALM'', v_groupby_fila, ''
             ORDER BY alm.NOMBRE_ALM_ALM'', v_groupby_fila
        );

        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;

    ELSE
        /* CASO B: ARTICULO SIMPLE (Sin atributos) */
        SELECT
            alm.NOMBRE_ALM_ALM as Almacen,
            COALESCE(SUM(stk.CANTIDAD_STK), 0) as `Stock Total`
        FROM fza_almacenes alm
        LEFT JOIN fza_articulos_stockactual stk
            ON alm.CODIGO_ALM_ALM = stk.CODIGO_ALM_STK
            AND stk.CODIGO_UNIDAD_STK = p_input
        WHERE alm.ESACTIVO_ALM = ''S''
        GROUP BY alm.NOMBRE_ALM_ALM
        ORDER BY alm.NOMBRE_ALM_ALM;

    END IF;
END ;;
DELIMITER ;


