--
-- Script idempotente: CREATE OR REPLACE, se puede aplicar repetidamente.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. Cabecera enriquecida (empresa + proveedor + totales)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW `vi_albaranes_compra_cab_print` AS
SELECT
  alb.`SERIE_ALBC`,
  alb.`NUMERO_ALBC`,
  alb.`FECHA_ALBC`,
  alb.`ESTADO_ALBC`,
  alb.`REF_PROVEEDOR_ALBC`,
