  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_compras_sesiones_documentos''
     AND COLUMN_NAME  = ''CODIGO_EMP_SESDOC'');
