  ''  `CONTADOR_LINEAS_PEDC` varchar(8)    NULL DEFAULT NULL,''
  ''  `COMENTARIOS_PEDC`     varchar(1000) NULL DEFAULT '''''''',''
  ''  `OBSERVACIONES_PEDC`   varchar(2000) NULL DEFAULT '''''''',''
  ''  `ESPIVOTE_HORIZONTAL_PEDC` varchar(1) NULL DEFAULT ''''N''''''
