  ''AFTER `NOMBRE_FAM_PEDCLIN`'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- Backfill best-effort para pedidos ya materializados: rescata
-- COLOR_TEXTO_SESLIN desde la sesion origen via
-- fza_compras_sesiones_documentos. Solo escribe filas que ahora estan
-- NULL para no pisar tecleos manuales.
UPDATE fza_pedidos_compra_lineas P
  JOIN fza_compras_sesiones_documentos D
    ON D.TIPO_DOC_SESDOC = ''PEDC''
   AND D.SERIE_SESDOC    = P.SERIE_PEDC_PEDCLIN
   AND D.NUMERO_SESDOC   = P.NUMERO_PEDC_PEDCLIN
  JOIN fza_compras_sesiones_lineas S
    ON S.SERIE_SES_SESLIN  = D.SERIE_SES_SESDOC
   AND S.NUMERO_SES_SESLIN = D.NUMERO_SES_SESDOC
   AND ( S.CODIGO_ART_TENTATIVO_SESLIN = P.CODIGO_ART_PEDCLIN
      OR S.CODIGO_ART_REUSAR_SESLIN    = P.CODIGO_ART_PEDCLIN )
   SET P.COLOR_TEXTO_PEDCLIN = S.COLOR_TEXTO_SESLIN
 WHERE P.COLOR_TEXTO_PEDCLIN IS NULL
   AND S.COLOR_TEXTO_SESLIN IS NOT NULL
   AND S.COLOR_TEXTO_SESLIN <> '''';

-- ----------------------------------------------------------------------------
-- 2bis. fza_pedidos_compra_celdas: cantidad por (linea, fila, talla)
-- Espejo de fza_albaranes_compra_celdas. Sufijo PEDCCEL. Soporta el modo
-- ''Tallas en horizontal'' del Mto: una celda por SKU dentro de la matriz
-- pivote por talla x color.
-- ----------------------------------------------------------------------------
SET @tab_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_pedidos_compra_celdas''
);
SET @ddl := IF(@tab_exists = 0,
  ''CREATE TABLE `fza_pedidos_compra_celdas` (''
  ''  `SERIE_PEDC_PEDCCEL`  varchar(20)   NOT NULL,''
  ''  `NUMERO_PEDC_PEDCCEL` varchar(20)   NOT NULL,''
  ''  `LINEA_PEDC_PEDCCEL`  varchar(4)    NOT NULL,''
  ''  `ID_FILA_PEDC_PEDCCEL` int(11)      NOT NULL DEFAULT 1,''
  ''  `ID_AV_PIVOT_PEDCCEL` int(11)       NOT NULL''
  ''       COMMENT ''''ID del valor de atributo (talla) que pivota'''',''
  ''  `CANTIDAD_PEDCCEL`    decimal(19,6) NOT NULL DEFAULT 0,''
  ''  `CODIGO_ALM_PEDCCEL`  varchar(10)   NULL DEFAULT NULL,''
  ''  `INSTANTE_MODIF` timestamp NOT NULL''
  ''       DEFAULT current_timestamp() ON UPDATE current_timestamp(),''
  ''  `INSTANTE_ALTA`  timestamp NOT NULL''
  ''       DEFAULT ''''0000-00-00 00:00:00'''',''
  ''  `USUARIO_ALTA`   varchar(100) NOT NULL,''
  ''  `USUARIO_MODIF`  varchar(100) NOT NULL,''
  ''  PRIMARY KEY (`SERIE_PEDC_PEDCCEL`,`NUMERO_PEDC_PEDCCEL`,''
  ''               `LINEA_PEDC_PEDCCEL`,`ID_FILA_PEDC_PEDCCEL`,''
  ''               `ID_AV_PIVOT_PEDCCEL`)''
  '')'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_pedidos_compra_celdas''
     AND INDEX_NAME   = ''IDX_PEDCCEL_LINEA''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_pedidos_compra_celdas` ''
  ''ADD INDEX `IDX_PEDCCEL_LINEA` ''
  ''(`SERIE_PEDC_PEDCCEL`,`NUMERO_PEDC_PEDCCEL`,`LINEA_PEDC_PEDCCEL`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ----------------------------------------------------------------------------
-- 3. Alinear fza_tipos_documentos: el codigo ''PC'' apunta a la tabla nueva.
--    Antes apuntaba a ''fza_pedidos_compras'' (plural) que no existia.
-- ----------------------------------------------------------------------------
UPDATE `fza_tipos_documentos`
   SET `TABLA_ORIGEN_TIPO_DOCUMENTO_TD` = ''fza_pedidos_compra''
 WHERE `CODIGO_TIPO_DOCUMENTO_TD` = ''PC''
   AND `TABLA_ORIGEN_TIPO_DOCUMENTO_TD` <> ''fza_pedidos_compra'';

-- Si no existe la entrada, la creamos para que el contador PRC_GET_CONTADOR_FACTURA
-- la conozca.
INSERT INTO `fza_tipos_documentos`
  (`CODIGO_TIPO_DOCUMENTO_TD`, `DESCRIPCION_TIPO_DOCUMENTO_TD`,
   `TABLA_ORIGEN_TIPO_DOCUMENTO_TD`)
SELECT ''PC'', ''PEDIDO DE COMPRAS'', ''fza_pedidos_compra''
 WHERE NOT EXISTS (
   SELECT 1 FROM `fza_tipos_documentos`
    WHERE `CODIGO_TIPO_DOCUMENTO_TD` = ''PC''
 );

-- ----------------------------------------------------------------------------
-- 3bis. Provisionar contador ''PC'' en fza_contadores si no existe.
--    Mismo patron que los demas tipos de documento (SERIE_CON=''-'' y
--    DEFAULT_CON=''S'' para que PRC_FNC_GET_NEXT_NRO_DOC lo localice).
-- ----------------------------------------------------------------------------
INSERT INTO `fza_contadores`
  (`TIPO_DOC_CON`, `EMPRESA_CON`, `SERIE_CON`, `CON`,
   `NUM_DIGITOS_CON`, `ESACTIVO_CON`, `DEFAULT_CON`,
   `INSTANTE_ALTA`, `USUARIO_ALTA`, `INSTANTE_MODIF`, `USUARIO_MODIF`)
SELECT ''PC'', ''-'', ''-'', 0, 6, ''S'', ''S'',
       NOW(), ''SISTEMA'', NOW(), ''SISTEMA''
 WHERE NOT EXISTS (
   SELECT 1 FROM `fza_contadores`
    WHERE `TIPO_DOC_CON` = ''PC'' AND `SERIE_CON` = ''-''
 );

-- ----------------------------------------------------------------------------
-- 4. Registrar el nuevo Mto en fza_winforms (idempotente)
-- ----------------------------------------------------------------------------
INSERT INTO `fza_winforms`
  (`CALL_WINF`, `CAPTION_WINF`, `MENUITEM_WINF`, `UNITF_WINF`,
   `SHORTCUT_WINF`, `DATAMODULE_WINF`, `NUM_VENTANAS_WINF`)
SELECT ''PedidosCompra'',
       ''Pedidos de Compra'',
       ''Pedidos1'',
       ''inMtoPedidosCompra.TfrmMtoPedidosCompra'',
       ''Ctrl+Alt+P'',
       ''UniDataPedidosCompra.TdmPedidosCompra'',
       5
 WHERE NOT EXISTS (
   SELECT 1 FROM `fza_winforms`
    WHERE `CALL_WINF` = ''PedidosCompra''
 );

-- ----------------------------------------------------------------------------
-- 5. Vista basica vi_pedidos_compra (lectura para tsLista)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW `vi_pedidos_compra` AS
SELECT  p.*,
        prv.NOMBRE_PRV         AS NOMBRE_PRV_PEDC,
        emp.RAZON_SOCIAL_EMP   AS RAZON_SOCIAL_EMPRESA_VIEW_PEDC
  FROM  fza_pedidos_compra p
  LEFT  JOIN fza_proveedores prv
         ON prv.CODIGO_PRV_PRV = p.CODIGO_PRV_PEDC
  LEFT  JOIN fza_empresas    emp
         ON emp.CODIGO_EMP_EMP = p.CODIGO_EMP_PEDC;
', '2026-05-29 06:17:40', '2026-05-29 06:17:40', 'Administrador', 'Administrador'),
  ('293', 'temporada_pedido', '-- ============================================================================
-- temporada_pedido.sql
--
-- Anyade ID_PV_TEMPORADA_PEDC a la cabecera de pedidos de compra,
-- analogo a ID_PV_TEMPORADA_SES en sesiones. La temporada se propaga:
--   sesion (ID_PV_TEMPORADA_SES)
--     -> pedido (ID_PV_TEMPORADA_PEDC) al materializar
--     -> modal "Crear albaran" se pre-rellena con la del pedido
--
-- FK logica a fza_propiedades_valores.ID_PV_ARTPROP con ID_PROP_PV=''TEMPORADA''.
--
-- Todo idempotente: chequea INFORMATION_SCHEMA antes de aplicar.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Columna ID_PV_TEMPORADA_PEDC en cabecera
-- ---------------------------------------------------------------------------
SET @col_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_pedidos_compra''
     AND COLUMN_NAME  = ''ID_PV_TEMPORADA_PEDC''
);
SET @ddl := IF(@col_exists = 0,
  ''ALTER TABLE `fza_pedidos_compra` ''
  ''ADD COLUMN `ID_PV_TEMPORADA_PEDC` int(11) NULL DEFAULT NULL ''
  ''  COMMENT ''''FK logica fza_propiedades_valores.ID_PV_ARTPROP con ''
  ''ID_PROP_PV=TEMPORADA. Se hereda de la sesion al materializar y ''
  ''se pre-rellena en el modal Crear Albaran al generar albaran desde pedido.'''''',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_pedidos_compra''
     AND INDEX_NAME   = ''IDX_PEDC_TEMPORADA''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_pedidos_compra` ''
  ''ADD INDEX `IDX_PEDC_TEMPORADA` (`ID_PV_TEMPORADA_PEDC`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------------------------------------------------------------------------
-- 2. Refrescar vi_pedidos_compra para exponer la nueva columna y el nombre
--    legible de la temporada (PV). Mantiene la forma original (p.*).
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW `vi_pedidos_compra` AS
SELECT  p.*,
        prv.NOMBRE_PRV         AS NOMBRE_PRV_PEDC,
        emp.RAZON_SOCIAL_EMP   AS RAZON_SOCIAL_EMPRESA_VIEW_PEDC,
        t.PV                   AS TEMPORADA_PEDC
  FROM  fza_pedidos_compra p
  LEFT  JOIN fza_proveedores prv
         ON prv.CODIGO_PRV_PRV = p.CODIGO_PRV_PEDC
  LEFT  JOIN fza_empresas    emp
         ON emp.CODIGO_EMP_EMP = p.CODIGO_EMP_PEDC
  LEFT  JOIN fza_propiedades_valores t
         ON t.ID_PV_ARTPROP    = p.ID_PV_TEMPORADA_PEDC
        AND t.ID_PROP_PV       = ''TEMPORADA'';
', '2026-05-29 08:10:48', '2026-05-29 08:10:48', 'Administrador', 'Administrador'),
  ('294', 'fix_contador_lineas_pedc', '-- =============================================================================
-- Fix CONTADOR_LINEAS_PEDC en fza_pedidos_compra
-- =============================================================================
-- Sincroniza el contador de lineas de la cabecera con la ultima LINEA real
-- almacenada en fza_pedidos_compra_lineas. Necesario al cambiar el alta de
-- lineas del Mto de pedidos de compra de un MAX(LINEA_PEDCLIN)+10 (que NO
-- tocaba el contador) al helper inLibContadorLineas.GetSiguienteLineaDoc
-- (UPDATE atomico de CONTADOR_LINEAS_PEDC +10).
--
-- Si un pedido tenia lineas anadidas a mano con el codigo viejo, su
-- CONTADOR_LINEAS_PEDC pudo quedar por detras del MAX(LINEA_PEDCLIN) real
-- (o NULL), y la primera linea nueva con el helper colisionaria con la PK
-- (NUMERO_PEDC_PEDCLIN, SERIE_PEDC_PEDCLIN, LINEA_PEDCLIN). Este script
-- resiembra el contador al maximo real para que el +10 siguiente no choque.
-- Los pedidos materializados ya tenian el contador sincronizado (la
-- materializacion lo fija a NLIN*10), asi que no se ven afectados.
--
-- CONTADOR_LINEAS_PEDC y LINEA_PEDCLIN son varchar: comparamos y guardamos
-- via CAST(... AS UNSIGNED) y LPAD a 8 digitos (formato del resto del
-- sistema).
--
-- Idempotente: se puede ejecutar varias veces sin efectos secundarios (tras
-- la primera pasada CONTADOR = ULTIMA_LINEA y el WHERE ya no casa).
-- =============================================================================

UPDATE fza_pedidos_compra AS C
   JOIN (
       SELECT SERIE_PEDC_PEDCLIN,
              NUMERO_PEDC_PEDCLIN,
              MAX(CAST(LINEA_PEDCLIN AS UNSIGNED)) AS ULTIMA_LINEA
         FROM fza_pedidos_compra_lineas
        GROUP BY SERIE_PEDC_PEDCLIN, NUMERO_PEDC_PEDCLIN
   ) AS L
     ON L.SERIE_PEDC_PEDCLIN  = C.SERIE_PEDC
    AND L.NUMERO_PEDC_PEDCLIN = C.NUMERO_PEDC
  SET C.CONTADOR_LINEAS_PEDC = LPAD(L.ULTIMA_LINEA, 8, ''0'')
WHERE C.CONTADOR_LINEAS_PEDC IS NULL
   OR CAST(C.CONTADOR_LINEAS_PEDC AS UNSIGNED) < L.ULTIMA_LINEA;
', '2026-05-30 07:26:38', '2026-05-30 07:26:38', 'Administrador', 'Administrador'),
  ('295', 'traspasos_caja', '-- ============================================================================
-- Traspasos en caja — solicitudes de traspaso entre almacenes
-- Diseno DDL siguiendo LIBRO_DE_ESTILO_BBDD.md
-- (detalle funcional en DESARROLLOS EN CURSO/traspasos_caja.md).
--
-- Crea las dos tablas del CICLO DE SOLICITUDES (peticion -> atencion):
--   fza_traspasos_solicitudes         (cabecera, sufijo TRSOL)
--   fza_traspasos_solicitudes_lineas  (lineas,   sufijo TRSOLLIN)
-- y siembra el contador global ''TS'' para numerar las solicitudes.
--
-- El TRASPASO EJECUTADO no necesita tablas nuevas: se graba en
-- fza_caja_operaciones (TIPO_OPERACION_OPCAJA TR/AT) + fza_movimientos_almacen
-- (par S+E). Estas tablas solo guardan la PETICION pendiente y su estado.
--
-- Idempotente: pasa por INFORMATION_SCHEMA (TABLES / STATISTICS) antes de crear
-- cada tabla e indice; el contador se siembra solo si no existe la fila global.
-- Sufijos TRSOL / TRSOLLIN dados de alta en LIBRO_DE_ESTILO_BBDD.md (§2) y en
-- src/utilnormbbdd/UNormalizerEngine.pas (InitDefaults).
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Cabecera de la solicitud (TRSOL)
-- ---------------------------------------------------------------------------
SET @tab_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_traspasos_solicitudes''
);
SET @ddl := IF(@tab_exists = 0,
  ''CREATE TABLE `fza_traspasos_solicitudes` (''
  ''  `NUMERO_TRSOL`             varchar(20)   NOT NULL,''
  ''  `SERIE_TRSOL`              varchar(20)   NOT NULL,''
  ''  `FECHA_TRSOL`              date          NULL DEFAULT NULL,''
  ''  `ESTADO_TRSOL`             varchar(20)   NOT NULL DEFAULT ''''PENDIENTE''''''
  ''       COMMENT ''''PENDIENTE, PARCIAL, ATENDIDA, RECHAZADA, CANCELADA'''',''
  ''  `CODIGO_EMP_TRSOL`         varchar(20)   NOT NULL,''
  ''  `CODIGO_ALM_ORIGEN_TRSOL`  varchar(10)   NOT NULL''
  ''       COMMENT ''''A quien se pide = origen del futuro traspaso'''',''
  ''  `CODIGO_ALM_DESTINO_TRSOL` varchar(10)   NOT NULL''
  ''       COMMENT ''''Quien pide = propio = destino del futuro traspaso'''',''
  ''  `CODIGO_EMP_CONTRA_TRSOL`  varchar(20)   NULL DEFAULT NULL,''
  ''  `CODIGO_CAJA_TRSOL`        varchar(10)   NULL DEFAULT NULL,''
  ''  `CODIGO_EMPLEADO_TRSOL`    varchar(20)   NULL DEFAULT NULL,''
  ''  `OBSERVACIONES_TRSOL`      varchar(1000) NULL DEFAULT '''''''',''
  ''  `INSTANTE_MODIF`           timestamp     NOT NULL''
  ''       DEFAULT current_timestamp() ON UPDATE current_timestamp(),''
  ''  `INSTANTE_ALTA`            timestamp     NOT NULL''
  ''       DEFAULT ''''0000-00-00 00:00:00'''',''
  ''  `USUARIO_ALTA`             varchar(100)  NOT NULL,''
  ''  `USUARIO_MODIF`            varchar(100)  NOT NULL,''
  ''  PRIMARY KEY (`NUMERO_TRSOL`,`SERIE_TRSOL`)''
  '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_traspasos_solicitudes''
     AND INDEX_NAME   = ''IDX_TRSOL_ESTADO''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_traspasos_solicitudes` ''
  ''ADD INDEX `IDX_TRSOL_ESTADO` (`ESTADO_TRSOL`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_traspasos_solicitudes''
     AND INDEX_NAME   = ''IDX_TRSOL_ORIGEN''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_traspasos_solicitudes` ''
  ''ADD INDEX `IDX_TRSOL_ORIGEN` (`CODIGO_ALM_ORIGEN_TRSOL`,`ESTADO_TRSOL`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_traspasos_solicitudes''
     AND INDEX_NAME   = ''IDX_TRSOL_DESTINO''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_traspasos_solicitudes` ''
  ''ADD INDEX `IDX_TRSOL_DESTINO` (`CODIGO_ALM_DESTINO_TRSOL`,`ESTADO_TRSOL`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_traspasos_solicitudes''
     AND INDEX_NAME   = ''IDX_TRSOL_EMP''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_traspasos_solicitudes` ''
  ''ADD INDEX `IDX_TRSOL_EMP` (`CODIGO_EMP_TRSOL`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------------------------------------------------------------------------
-- 2. Lineas de la solicitud (TRSOLLIN)
-- ---------------------------------------------------------------------------
SET @tab_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_traspasos_solicitudes_lineas''
);
SET @ddl := IF(@tab_exists = 0,
  ''CREATE TABLE `fza_traspasos_solicitudes_lineas` (''
  ''  `NUMERO_TRSOL_TRSOLLIN`         varchar(20)   NOT NULL,''
  ''  `SERIE_TRSOL_TRSOLLIN`          varchar(20)   NOT NULL,''
  ''  `LINEA_TRSOLLIN`                varchar(4)    NOT NULL,''
  ''  `CODIGO_ART_TRSOLLIN`           varchar(20)   NULL DEFAULT NULL,''
  ''  `CODIGO_UNIDAD_TRSOLLIN`        varchar(50)   NOT NULL''
  ''       COMMENT ''''SKU solicitado'''',''
  ''  `DESCRIPCION_ARTICULO_TRSOLLIN` varchar(100)  NULL DEFAULT NULL,''
  ''  `CANTIDAD_PEDIDA_TRSOLLIN`      decimal(19,6) NOT NULL DEFAULT ''''0.000000'''',''
  ''  `CANTIDAD_SERVIDA_TRSOLLIN`     decimal(19,6) NOT NULL DEFAULT ''''0.000000''''''
  ''       COMMENT ''''Unidades ya atendidas (para estado PARCIAL)'''',''
  ''  `ESATENDIDA_TRSOLLIN`           varchar(1)    NOT NULL DEFAULT ''''N'''',''
  ''  `INSTANTE_MODIF`                timestamp     NOT NULL''
  ''       DEFAULT current_timestamp() ON UPDATE current_timestamp(),''
  ''  `INSTANTE_ALTA`                 timestamp     NOT NULL''
  ''       DEFAULT ''''0000-00-00 00:00:00'''',''
  ''  `USUARIO_ALTA`                  varchar(100)  NOT NULL,''
  ''  `USUARIO_MODIF`                 varchar(100)  NOT NULL,''
  ''  PRIMARY KEY (`NUMERO_TRSOL_TRSOLLIN`,`SERIE_TRSOL_TRSOLLIN`,''
  ''               `LINEA_TRSOLLIN`)''
  '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_traspasos_solicitudes_lineas''
     AND INDEX_NAME   = ''IDX_TRSOLLIN_SKU''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_traspasos_solicitudes_lineas` ''
  ''ADD INDEX `IDX_TRSOLLIN_SKU` (`CODIGO_UNIDAD_TRSOLLIN`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------------------------------------------------------------------------
-- 3. Contador global de solicitudes de traspaso (TIPO_DOC = ''TS'')
-- Lo consume inLibtb.ObtenerSiguienteContador(''TS'') (SP PRC_GET_NEXT_CONT).
-- Se siembra solo si no existe ya la fila global (''TS'',''-'',''-'').
-- ---------------------------------------------------------------------------
INSERT INTO `fza_contadores`
  (`TIPO_DOC_CON`, `EMPRESA_CON`, `SERIE_CON`, `CON`, `NUM_DIGITOS_CON`,
   `ESACTIVO_CON`, `DEFAULT_CON`, `INSTANTE_ALTA`, `USUARIO_ALTA`,
   `USUARIO_MODIF`)
SELECT ''TS'', ''-'', ''-'', 0, 10, ''S'', ''S'', NOW(), ''SISTEMA'', ''SISTEMA''
 WHERE NOT EXISTS (
   SELECT 1 FROM `fza_contadores`
    WHERE `TIPO_DOC_CON` = ''TS''
      AND `EMPRESA_CON` = ''-''
      AND `SERIE_CON` = ''-'');
