SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_devoluciones_compra''
     AND INDEX_NAME   = ''IDX_DEVC_EMPRESA''
);
SET @ddl := IF(@idx_exists = 0,
