SET @s := IF(@c = 0,
  ''ALTER TABLE `fza_devoluciones_compra_lineas`
     ADD COLUMN `REF_PRV_DEVCLIN` varchar(100) NULL DEFAULT NULL
     AFTER `CODIGO_UNIDAD_DEVCLIN`'',
