PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Re-crear la vista para que `a.*` exponga las columnas recien anyadidas
-- (MariaDB congela la lista de columnas al crear la vista).
CREATE OR REPLACE VIEW `vi_devoluciones_compra` AS
SELECT  a.*,
        prv.NOMBRE_PRV         AS NOMBRE_PRV_DEVC,
        emp.RAZON_SOCIAL_EMP   AS RAZON_SOCIAL_EMPRESA_VIEW_DEVC
  FROM  fza_devoluciones_compra a
  LEFT  JOIN fza_proveedores prv
         ON prv.CODIGO_PRV_PRV = a.CODIGO_PRV_DEVC
  LEFT  JOIN fza_empresas    emp
         ON emp.CODIGO_EMP_EMP = a.CODIGO_EMP_DEVC;
', '2026-06-09 17:18:28', '2026-06-09 17:18:28', 'Administrador', 'Administrador'),
  ('341', 'vi_devoluciones_compra_print', '-- =============================================================================
-- Vistas para la impresion del devolucion de compra
-- Analogo a vi_compras_sesiones_*_print pero contra el modelo de devoluciones
-- de compra (cabecera + lineas; sin tabla de celdas separada — los SKUs
-- viven directamente en fza_devoluciones_compra_lineas y la talla se deduce
-- del atributo CO/TAL del SKU).
--
-- Script idempotente: CREATE OR REPLACE, se puede aplicar repetidamente.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. Cabecera enriquecida (empresa + proveedor + almacen destino + totales)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW `vi_devoluciones_compra_cab_print` AS
SELECT
  alb.`SERIE_DEVC`,
  alb.`NUMERO_DEVC`,
  alb.`FECHA_DEVC`,
  alb.`ESTADO_DEVC`,
  alb.`REF_PROVEEDOR_DEVC`,
  alb.`COMENTARIOS_DEVC`,
  alb.`OBSERVACIONES_DEVC`,
  alb.`CODIGO_EMP_DEVC`,
  emp.`RAZON_SOCIAL_EMP`,
  emp.`DIRECCION1_EMP`,
  emp.`CODIGO_POSTAL_EMP`,
  emp.`POBLACION_EMP`,
  emp.`PROVINCIA_EMP`,
  emp.`NIF_EMP`        AS `CIF_EMP`,
  emp.`MOVIL_EMP`      AS `TELEFONO1_EMP`,
  alb.`CODIGO_PRV_DEVC`,
  prv.`RAZON_SOCIAL_PRV`,
  prv.`DIRECCION1_PRV`,
  prv.`CODIGO_POSTAL_PRV`,
  prv.`POBLACION_PRV`,
  prv.`PROVINCIA_PRV`,
  prv.`NIF_PRV`        AS `CIF_PRV`,
  COALESCE(prv.`TELEFONO_PRV`, prv.`MOVIL_PRV`) AS `TELEFONO1_PRV`,
  -- Almacen destino: el codigo vive en la cabecera (CODIGO_ALM_DEVC) y
  -- los datos descriptivos se resuelven via JOIN a fza_almacenes. No
  -- snapshoteamos como con empresa/proveedor: si cambia la direccion
  -- del almacen, los devoluciones historicos mostraran la actual.
  alb.`CODIGO_ALM_DEVC`,
  alm.`NOMBRE_ALM_ALM`  AS `NOMBRE_ALM_DEVC`,
  alm.`DIRECCION_ALM`   AS `DIRECCION_ALM_DEVC`,
  alm.`CODIGO_POSTAL_ALM` AS `CODIGO_POSTAL_ALM_DEVC`,
  alm.`POBLACION_ALM`   AS `POBLACION_ALM_DEVC`,
  alm.`PROVINCIA_ALM`   AS `PROVINCIA_ALM_DEVC`,
  alm.`TELEFONO_ALM`    AS `TELEFONO_ALM_DEVC`,
  alm.`EMAIL_ALM`       AS `EMAIL_ALM_DEVC`,
  alb.`CODIGO_IVA_DEVC`,
  alb.`PORCENTAJE_IVAN_DEVC`,
  alb.`PORCENTAJE_IVAR_DEVC`,
  alb.`PORCENTAJE_IVAS_DEVC`,
  alb.`PORCENTAJE_IVAE_DEVC`,
  alb.`TOTAL_BASES_DEVC`,
  alb.`TOTAL_IMPUESTOS_DEVC`,
  alb.`TOTAL_LIQUIDO_DEVC`,
  alb.`INSTANTE_ALTA`,
  alb.`USUARIO_ALTA`,
  -- Agregados de las lineas
  (SELECT COALESCE(SUM(`CANTIDAD_DEVCLIN`), 0)
     FROM `fza_devoluciones_compra_lineas` lin
    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`
      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `TOTAL_UNIDADES_SES`,
  (SELECT COALESCE(SUM(`TOTAL_DEVCLIN`), 0)
     FROM `fza_devoluciones_compra_lineas` lin
    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`
      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `TOTAL_LINEAS_SES`,
  (SELECT COUNT(*)
     FROM `fza_devoluciones_compra_lineas` lin
    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`
      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `NUM_LINEAS_SES`
FROM `fza_devoluciones_compra` alb
LEFT JOIN `fza_empresas`     emp ON emp.`CODIGO_EMP_EMP` = alb.`CODIGO_EMP_DEVC`
LEFT JOIN `fza_proveedores`  prv ON prv.`CODIGO_PRV_PRV` = alb.`CODIGO_PRV_DEVC`
LEFT JOIN `fza_almacenes`    alm ON alm.`CODIGO_ALM_ALM` = alb.`CODIGO_ALM_DEVC`;

-- ---------------------------------------------------------------------------
-- 2. Lineas con T01..T20 pivotadas por talla
-- ---------------------------------------------------------------------------
-- Como en devolucion cada linea ya es un SKU, agrupamos por (articulo, color
-- derivado del SKU, ID_AC_PIVOT, almacen destino) y sumamos
-- CANTIDAD_DEVCLIN en la posicion correspondiente del conjunto pivot. La
-- talla del SKU se obtiene de fza_atributos_sku (atributo con
-- ID_VA_AV=''TAL''). El color se obtiene del mismo modo (atributo con
-- ID_VA_AV=''CO'' -> CODIGO_ATB/NOMBRE_ATB del atributo basico, o fallback
-- al segundo segmento del SKU).
-- IMPORTANTE: el color forma parte de la clave de agrupacion. Sin el, las
-- lineas de varios colores del mismo articulo + sistema de tallas se
-- colapsaban en una unica fila y los SUM por talla sumaban todas las
-- cantidades juntas (impresion horizontal mostraba 1 fila con la suma de
-- los 4 colores). El GROUP BY incluye CODIGO_ATB_COLOR + NOMBRE_COLOR
-- (color via atributo basico) y el segmento medio del SKU (fallback para
-- SKUs sin atributo CO).
-- Tambien forma parte de la clave el CODIGO_ALMACEN_DEVCLIN: en devoluciones
-- agrupados (mezclan varios almacenes destino aunque la cabecera tenga
-- uno principal) las lineas de un mismo articulo en distintos almacenes
-- aparecen como filas separadas, una por almacen, para que el .frx pueda
-- imprimir junto a cada linea el almacen al que va destinada.
CREATE OR REPLACE VIEW `vi_devoluciones_compra_lin_print` AS
WITH `pos_acd` AS (
  SELECT
    `ID_AC_ACD` AS `ID_AC`,
    `ID_AV_ACD` AS `ID_AV`,
    ROW_NUMBER() OVER (
      PARTITION BY `ID_AC_ACD`
      ORDER BY `ORDEN_ACD`, `ID_AV_ACD`
    ) AS `POSICION`
  FROM `fza_atributos_conjuntos_det`
),
`sku_talla` AS (
  SELECT
    sa.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,
    sa.`ID_AV_SA`             AS `ID_AV_TALLA`
  FROM `fza_atributos_sku` sa
  JOIN `fza_atributos_valores` av
    ON av.`ID_AV` = sa.`ID_AV_SA`
   AND av.`ID_VA_AV` = ''TAL''
),
`sku_color` AS (
  SELECT
    sa.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,
    atb.`CODIGO_ATB`          AS `CODIGO_ATB_COLOR`,
    atb.`NOMBRE_ATB`          AS `NOMBRE_COLOR`
  FROM `fza_atributos_sku` sa
  JOIN `fza_atributos_valores` av
    ON av.`ID_AV` = sa.`ID_AV_SA`
   AND av.`ID_VA_AV` = ''CO''
  LEFT JOIN `fza_atributos_basicos` atb
    ON atb.`ID_ATB` = av.`ID_ATB_AV`
)
SELECT
  L.`SERIE_DEVC_DEVCLIN`            AS `SERIE_DEVC`,
  L.`NUMERO_DEVC_DEVCLIN`           AS `NUMERO_DEVC`,
  MIN(L.`LINEA_DEVCLIN`)            AS `LINEA_DEVC`,
  L.`CODIGO_ART_DEVCLIN`            AS `CODIGO_ART`,
  COALESCE(MIN(L.`REF_PRV_DEVCLIN`), '''') AS `REF_PRV`,
  MIN(L.`DESCRIPCION_ARTICULO_DEVCLIN`) AS `DESCRIPCION`,
  COALESCE(MIN(sc.`NOMBRE_COLOR`),
           SUBSTRING_INDEX(SUBSTRING_INDEX(MIN(L.`CODIGO_UNIDAD_DEVCLIN`), ''/'', 2), ''/'', -1),
           '''')                      AS `COLOR_TEXTO`,
  COALESCE(MIN(sc.`CODIGO_ATB_COLOR`), '''') AS `CODIGO_ATB_COLOR`,
  AVG(L.`PRECIO_COMPRA_SIVA_ARTICULO_DEVCLIN`) AS `PRECIO_COMPRA`,
  0                                 AS `PRECIO_VENTA`,
  L.`ID_AC_PIVOT_DEVCLIN`           AS `ID_AC_PIVOT`,
  ac.`NOMBRE_AC`,
  COALESCE(ac.`NOMBRE_CORTO_AC`, UPPER(LEFT(ac.`NOMBRE_AC`, 8))) AS `NOMBRE_CORTO_AC`,
  -- Almacen destino de la linea (clave de agrupacion). El JOIN a
  -- fza_almacenes expone los campos descriptivos del almacen para
  -- que el .frx los pueda imprimir junto a cada linea. Si la
  -- cabecera CODIGO_ALM_DEVC coincide con todas las lineas, ambos
  -- niveles muestran lo mismo; en devoluciones agrupados con varios
  -- almacenes, cada linea reflejara su propio destino.
  L.`CODIGO_ALMACEN_DEVCLIN`        AS `CODIGO_ALM_DEVCLIN`,
  MIN(alm.`CODIGO_EMP_ALM`)         AS `CODIGO_EMP_ALM_DEVCLIN`,
  MIN(alm.`NOMBRE_ALM_ALM`)         AS `NOMBRE_ALM_DEVCLIN`,
  MIN(alm.`DIRECCION_ALM`)          AS `DIRECCION_ALM_DEVCLIN`,
  MIN(alm.`CODIGO_POSTAL_ALM`)      AS `CODIGO_POSTAL_ALM_DEVCLIN`,
  MIN(alm.`POBLACION_ALM`)          AS `POBLACION_ALM_DEVCLIN`,
  MIN(alm.`PROVINCIA_ALM`)          AS `PROVINCIA_ALM_DEVCLIN`,
  MIN(alm.`TELEFONO_ALM`)           AS `TELEFONO_ALM_DEVCLIN`,
  MIN(alm.`EMAIL_ALM`)              AS `EMAIL_ALM_DEVCLIN`,
  SUM(L.`CANTIDAD_DEVCLIN`)         AS `TOTAL_UNIDADES`,
  SUM(L.`TOTAL_DEVCLIN`)            AS `TOTAL_LINEA`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  1 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T01`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  2 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T02`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  3 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T03`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  4 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T04`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  5 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T05`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  6 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T06`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  7 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T07`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  8 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T08`,
  COALESCE(SUM(CASE WHEN p.`POSICION` =  9 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T09`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 10 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T10`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 11 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T11`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 12 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T12`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 13 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T13`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 14 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T14`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 15 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T15`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 16 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T16`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 17 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T17`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 18 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T18`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 19 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T19`,
  COALESCE(SUM(CASE WHEN p.`POSICION` = 20 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T20`
FROM `fza_devoluciones_compra_lineas` L
LEFT JOIN `fza_atributos_conjuntos` ac
       ON ac.`ID_AC` = L.`ID_AC_PIVOT_DEVCLIN`
LEFT JOIN `sku_talla` st
       ON st.`CODIGO_UNIDAD` = L.`CODIGO_UNIDAD_DEVCLIN`
LEFT JOIN `pos_acd` p
       ON p.`ID_AC` = L.`ID_AC_PIVOT_DEVCLIN`
      AND p.`ID_AV` = st.`ID_AV_TALLA`
LEFT JOIN `sku_color` sc
       ON sc.`CODIGO_UNIDAD` = L.`CODIGO_UNIDAD_DEVCLIN`
LEFT JOIN `fza_almacenes` alm
       ON alm.`CODIGO_ALM_ALM` = L.`CODIGO_ALMACEN_DEVCLIN`
GROUP BY
  L.`SERIE_DEVC_DEVCLIN`, L.`NUMERO_DEVC_DEVCLIN`,
  L.`CODIGO_ART_DEVCLIN`,
  L.`ID_AC_PIVOT_DEVCLIN`, ac.`NOMBRE_AC`, ac.`NOMBRE_CORTO_AC`,
  sc.`CODIGO_ATB_COLOR`, sc.`NOMBRE_COLOR`,
  SUBSTRING_INDEX(SUBSTRING_INDEX(L.`CODIGO_UNIDAD_DEVCLIN`, ''/'', 2), ''/'', -1),
  L.`CODIGO_ALMACEN_DEVCLIN`;

-- ---------------------------------------------------------------------------
-- 3. Guias de tallas (mismas que en sesiones — depende solo de conjuntos)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW `vi_devoluciones_compra_guias_print` AS
WITH `pos_acd` AS (
  SELECT
    acd.`ID_AC_ACD` AS `ID_AC`,
    acd.`ID_AV_ACD` AS `ID_AV`,
    av.`AV`,
    ROW_NUMBER() OVER (
      PARTITION BY acd.`ID_AC_ACD`
      ORDER BY acd.`ORDEN_ACD`, acd.`ID_AV_ACD`
    ) AS `POSICION`
  FROM `fza_atributos_conjuntos_det` acd
  INNER JOIN `fza_atributos_valores` av ON av.`ID_AV` = acd.`ID_AV_ACD`
)
SELECT
  ac.`ID_AC`,
  ac.`NOMBRE_AC`,
  COALESCE(ac.`NOMBRE_CORTO_AC`, UPPER(LEFT(ac.`NOMBRE_AC`, 8))) AS `NOMBRE_CORTO_AC`,
  MAX(CASE WHEN p.`POSICION` =  1 THEN p.`AV` END) AS `T01`,
  MAX(CASE WHEN p.`POSICION` =  2 THEN p.`AV` END) AS `T02`,
  MAX(CASE WHEN p.`POSICION` =  3 THEN p.`AV` END) AS `T03`,
  MAX(CASE WHEN p.`POSICION` =  4 THEN p.`AV` END) AS `T04`,
  MAX(CASE WHEN p.`POSICION` =  5 THEN p.`AV` END) AS `T05`,
  MAX(CASE WHEN p.`POSICION` =  6 THEN p.`AV` END) AS `T06`,
  MAX(CASE WHEN p.`POSICION` =  7 THEN p.`AV` END) AS `T07`,
  MAX(CASE WHEN p.`POSICION` =  8 THEN p.`AV` END) AS `T08`,
  MAX(CASE WHEN p.`POSICION` =  9 THEN p.`AV` END) AS `T09`,
  MAX(CASE WHEN p.`POSICION` = 10 THEN p.`AV` END) AS `T10`,
  MAX(CASE WHEN p.`POSICION` = 11 THEN p.`AV` END) AS `T11`,
  MAX(CASE WHEN p.`POSICION` = 12 THEN p.`AV` END) AS `T12`,
  MAX(CASE WHEN p.`POSICION` = 13 THEN p.`AV` END) AS `T13`,
  MAX(CASE WHEN p.`POSICION` = 14 THEN p.`AV` END) AS `T14`,
  MAX(CASE WHEN p.`POSICION` = 15 THEN p.`AV` END) AS `T15`,
  MAX(CASE WHEN p.`POSICION` = 16 THEN p.`AV` END) AS `T16`,
  MAX(CASE WHEN p.`POSICION` = 17 THEN p.`AV` END) AS `T17`,
  MAX(CASE WHEN p.`POSICION` = 18 THEN p.`AV` END) AS `T18`,
  MAX(CASE WHEN p.`POSICION` = 19 THEN p.`AV` END) AS `T19`,
  MAX(CASE WHEN p.`POSICION` = 20 THEN p.`AV` END) AS `T20`
FROM `fza_atributos_conjuntos` ac
INNER JOIN `pos_acd` p ON p.`ID_AC` = ac.`ID_AC`
WHERE p.`POSICION` <= 20
  AND ac.`ESACTIVO_AC` = ''S''
GROUP BY ac.`ID_AC`, ac.`NOMBRE_AC`, ac.`NOMBRE_CORTO_AC`;
', '2026-06-09 17:18:34', '2026-06-09 17:18:34', 'Administrador', 'Administrador'),
  ('342', 'familias_asignar_codigo_padre', '-- =============================================================================
-- Asigna el codigo padre de cada familia a partir del prefijo del codigo
-- =============================================================================
-- Regla de negocio:
--   El codigo de una familia "hoja" contiene como prefijo el codigo de su
--   familia padre. La convencion Herreras usa pares de chars (ver
--   inLibMigFamilias.pas §v1.2):
--     - "01"    SECCION (padre)
--     - "0101"  FAMILIA (hijo de "01")
--     - "0202"  FAMILIA (hijo de "02")
--     - "1401"  FAMILIA (hijo de "14")
--
--   Es decir, los primeros (LEN - 2) chars del codigo hijo coinciden con
--   el codigo del padre. Solo asignamos el padre si la familia candidata
--   realmente existe en la tabla.
--
-- Que rellena:
--   Ambas columnas de "padre" en fza_articulos_familias:
--     - CODIGO_SUBFAMILIA_FAM   columna legacy, la que lee la UI hoy
--                               (inMtoFamilias.dfm: grid y ficha)
--     - CODIGO_PADRE_FAM        columna nueva (DESARROLLOS EN CURSO/
--                               familias_codigo_padre.sql), la que
--                               rellena el migrador SQL Server -> MariaDB
--
--   Mantenerlas sincronizadas evita que la UI muestre vacio el "Codigo
--   Subfamilia" cuando solo se ha rellenado la columna nueva.
--
-- Idempotente:
--   - El WHERE solo actualiza si alguna de las dos columnas no coincide
--     con el padre calculado.
--   - Re-ejecutarlo no produce cambios si el estado ya es coherente.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- PREVIEW (opcional): descomenta para ver que familias se actualizarian
-- y a que padre apuntarian, antes del UPDATE real.
-- -----------------------------------------------------------------------------
-- SELECT f.CODIGO_FAM_FAM                                  AS HIJO,
--        f.NOMBRE_FAM_FAM                                  AS NOMBRE_HIJO,
--        f.CODIGO_SUBFAMILIA_FAM                           AS SUBFAM_ACTUAL,
--        f.CODIGO_PADRE_FAM                                AS PADRE_ACTUAL,
--        p.CODIGO_FAM_FAM                                  AS PADRE_NUEVO,
--        p.NOMBRE_FAM_FAM                                  AS NOMBRE_PADRE
--   FROM fza_articulos_familias f
--   JOIN fza_articulos_familias p
--     ON p.CODIGO_FAM_FAM = SUBSTRING(f.CODIGO_FAM_FAM, 1,
--                                     CHAR_LENGTH(f.CODIGO_FAM_FAM) - 2)
--  WHERE CHAR_LENGTH(f.CODIGO_FAM_FAM) > 2
--    AND (COALESCE(f.CODIGO_SUBFAMILIA_FAM, '''') <> p.CODIGO_FAM_FAM
--      OR COALESCE(f.CODIGO_PADRE_FAM, '''')      <> p.CODIGO_FAM_FAM)
--  ORDER BY f.CODIGO_FAM_FAM;

-- -----------------------------------------------------------------------------
-- UPDATE: asigna el codigo padre deducido del prefijo en ambas columnas
-- -----------------------------------------------------------------------------
-- Usamos JOIN contra la propia tabla para validar que el padre candidato
-- existe — si "0101" tuviera prefijo "01" pero no hubiera fila "01" en la
-- tabla, no inventamos un padre inexistente y dejamos las columnas como
-- estan.
UPDATE fza_articulos_familias f
  JOIN fza_articulos_familias p
    ON p.CODIGO_FAM_FAM = SUBSTRING(f.CODIGO_FAM_FAM, 1,
                                    CHAR_LENGTH(f.CODIGO_FAM_FAM) - 2)
   SET f.CODIGO_SUBFAMILIA_FAM = p.CODIGO_FAM_FAM,
       f.CODIGO_PADRE_FAM      = p.CODIGO_FAM_FAM,
       f.INSTANTE_MODIF        = CURRENT_TIMESTAMP,
       f.USUARIO_MODIF         = ''SCRIPT_ASIGNAR_PADRE_FAM''
 WHERE CHAR_LENGTH(f.CODIGO_FAM_FAM) > 2
   AND (COALESCE(f.CODIGO_SUBFAMILIA_FAM, '''') <> p.CODIGO_FAM_FAM
     OR COALESCE(f.CODIGO_PADRE_FAM, '''')      <> p.CODIGO_FAM_FAM);

-- -----------------------------------------------------------------------------
-- ROLLBACK: si necesitas deshacerlo, vuelve a poner en NULL las filas
-- marcadas por este script:
--   UPDATE fza_articulos_familias
--      SET CODIGO_SUBFAMILIA_FAM = NULL,
--          CODIGO_PADRE_FAM      = NULL
--    WHERE USUARIO_MODIF = ''SCRIPT_ASIGNAR_PADRE_FAM'';
-- -----------------------------------------------------------------------------
', '2026-06-10 07:20:50', '2026-06-10 07:20:50', 'Administrador', 'Administrador'),
  ('343', 'familias_ajustar_contador_art', '-- =============================================================================
-- Ajusta CONTADOR_ART_FAM al ultimo numero realmente usado por los articulos
-- =============================================================================
-- CONTADOR_ART_FAM guarda el ULTIMO numero emitido por la familia para
-- autogenerar el codigo del articulo. El proximo articulo creado usara
-- CONTADOR_ART_FAM + 1 rellenado a PAD_ART_FAM digitos (ver
-- inLibComprasSesiones.pas:1115 — `iCont := CONTADOR + 1`).
--
-- Patron del codigo de articulo autogenerado:
--   CODIGO_ART_ART = CODIGO_FAM_FAM || LPAD(n, PAD_ART_FAM, ''0'')
--
--   Ej (familia "0101", pad 5, contador 15):
--     proximo articulo -> "0101" + "00016" = "010100016"
--
-- Que hace este script:
--   Para cada familia, busca todos los articulos cuyo codigo:
--     - empiezan por el codigo de la familia, y
--     - el sufijo restante es enteramente numerico (REGEXP ''^[0-9]+$'').
--   El MAX de ese sufijo es "el ultimo numero usado realmente". Si es
--   mayor que el CONTADOR_ART_FAM actual (o este es NULL), lo sube.
--
--   No se filtra por ESCONTADOR_ART_FAM: si una familia tiene articulos
--   que siguen el patron, dejamos el contador al dia aunque la familia
--   no este marcada como autogeneradora — el dia que se active el flag
--   ya esta listo para emitir el siguiente sin colisionar.
--
-- Idempotente:
--   - El WHERE no actualiza si el contador ya es >= MAX.
--   - Re-ejecutar no hace cambios y nunca baja un contador.
--
-- Familias afectadas tipicas (Herreras):
--   "0101", "0202", "1401"... con articulos "010100015", "020200003"...
--   tras ejecutar este script, CONTADOR_ART_FAM = 15, 3, etc.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- PREVIEW (opcional): muestra el cambio que se aplicaria por familia.
-- -----------------------------------------------------------------------------
-- SELECT f.CODIGO_FAM_FAM,
--        f.NOMBRE_FAM_FAM,
--        f.CONTADOR_ART_FAM       AS CONTADOR_ACTUAL,
--        m.MAX_NUM                AS CONTADOR_NUEVO,
--        m.NUM_ARTICULOS          AS ARTICULOS_PATRON
--   FROM fza_articulos_familias f
--   JOIN (
--       SELECT a.CODIGO_FAM_ART AS CODIGO_FAM,
--              COUNT(*)         AS NUM_ARTICULOS,
--              MAX(CAST(SUBSTRING(a.CODIGO_ART_ART,
--                                 CHAR_LENGTH(a.CODIGO_FAM_ART) + 1)
--                       AS UNSIGNED))         AS MAX_NUM
--         FROM fza_articulos a
--        WHERE a.CODIGO_FAM_ART IS NOT NULL
--          AND a.CODIGO_FAM_ART <> ''''
--          AND CHAR_LENGTH(a.CODIGO_ART_ART) >
--              CHAR_LENGTH(a.CODIGO_FAM_ART)
--          AND SUBSTRING(a.CODIGO_ART_ART, 1,
--                        CHAR_LENGTH(a.CODIGO_FAM_ART)) = a.CODIGO_FAM_ART
--          AND SUBSTRING(a.CODIGO_ART_ART,
--                        CHAR_LENGTH(a.CODIGO_FAM_ART) + 1) REGEXP ''^[0-9]+$''
--        GROUP BY a.CODIGO_FAM_ART
--   ) m ON m.CODIGO_FAM = f.CODIGO_FAM_FAM
--  WHERE f.CONTADOR_ART_FAM IS NULL
--     OR f.CONTADOR_ART_FAM < m.MAX_NUM
--  ORDER BY f.CODIGO_FAM_FAM;

-- -----------------------------------------------------------------------------
-- UPDATE: sube CONTADOR_ART_FAM al MAX de los sufijos numericos reales
-- -----------------------------------------------------------------------------
UPDATE fza_articulos_familias f
  JOIN (
      SELECT a.CODIGO_FAM_ART AS CODIGO_FAM,
             MAX(CAST(SUBSTRING(a.CODIGO_ART_ART,
                                CHAR_LENGTH(a.CODIGO_FAM_ART) + 1)
                      AS UNSIGNED))         AS MAX_NUM
        FROM fza_articulos a
       WHERE a.CODIGO_FAM_ART IS NOT NULL
         AND a.CODIGO_FAM_ART <> ''''
         AND CHAR_LENGTH(a.CODIGO_ART_ART) >
             CHAR_LENGTH(a.CODIGO_FAM_ART)
         AND SUBSTRING(a.CODIGO_ART_ART, 1,
                       CHAR_LENGTH(a.CODIGO_FAM_ART)) = a.CODIGO_FAM_ART
         AND SUBSTRING(a.CODIGO_ART_ART,
                       CHAR_LENGTH(a.CODIGO_FAM_ART) + 1) REGEXP ''^[0-9]+$''
       GROUP BY a.CODIGO_FAM_ART
  ) m ON m.CODIGO_FAM = f.CODIGO_FAM_FAM
   SET f.CONTADOR_ART_FAM = m.MAX_NUM,
       f.INSTANTE_MODIF   = CURRENT_TIMESTAMP,
       f.USUARIO_MODIF    = ''SCRIPT_AJUSTAR_CONTADOR_FAM''
 WHERE f.CONTADOR_ART_FAM IS NULL
    OR f.CONTADOR_ART_FAM < m.MAX_NUM;

-- -----------------------------------------------------------------------------
-- ROLLBACK: no hay rollback util — este script SOLO sube contadores nunca
-- los baja. Si necesitas dejar un contador a un valor concreto, hazlo a
-- mano. Las filas tocadas quedan marcadas con USUARIO_MODIF para auditar:
--   SELECT CODIGO_FAM_FAM, CONTADOR_ART_FAM, INSTANTE_MODIF
--     FROM fza_articulos_familias
--    WHERE USUARIO_MODIF = ''SCRIPT_AJUSTAR_CONTADOR_FAM'';
-- -----------------------------------------------------------------------------
', '2026-06-10 07:20:59', '2026-06-10 07:20:59', 'Administrador', 'Administrador'),
  ('344', 'propiedades_por_unidad', '-- ============================================================================
-- propiedades_por_unidad.sql  —  FASE 1 (modelo de datos)
--
-- Amplia el espectro de fza_articulos_propiedades para que CUALQUIER propiedad
-- (TEMPORADA, MATERIAL, ...) pueda vivir a tres niveles, replicando el mismo
-- mecanismo que ya usan tarifas (CODIGO_UNIDAD_ARTTAR) y fotos
-- (CODIGO_UNIDAD_FOT):
--
--   CODIGO_UNIDAD_ARTPROP = ''''                 -> propiedad del ARTICULO (padre)
--   CODIGO_UNIDAD_ARTPROP = ''ART/COLOR''        -> propiedad del COLOR (sku parcial)
--   CODIGO_UNIDAD_ARTPROP = ''ART/COLOR/TALLA''  -> propiedad del SKU completo
--
-- Resolucion efectiva (igual que ResolverPrecio de tarifas): se coge la fila
-- mas especifica que exista y, si no hay, se cae al nivel superior:
--   SKU completo  ->  COLOR  ->  ARTICULO ('''').
--
-- El "color" es el prefijo del SKU hasta antes de la talla, tal como ya hace
-- el fallback de fotos (ej: ''BLUS-SEDA/BLANCO'' para el SKU ''BLUS-SEDA/BLANCO/L'').
--
-- Que propiedades pueden bajar de nivel lo declara la nueva columna
-- NIVEL_PROP de fza_propiedades (ARTICULO < COLOR < SKU). TEMPORADA -> COLOR.
--
-- NO destruye datos: la columna nueva entra con DEFAULT '''' , asi que todas las
-- filas actuales quedan como "nivel ARTICULO" = comportamiento de hoy. La app
-- no necesita cambios para seguir funcionando tras este script.
--
-- Todo idempotente: chequea INFORMATION_SCHEMA antes de aplicar; re-ejecutable.
-- NO se toca factuzam_original.sql (regla dura del repo).
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Columna CODIGO_UNIDAD_ARTPROP en fza_articulos_propiedades
-- ---------------------------------------------------------------------------
SET @col_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_articulos_propiedades''
     AND COLUMN_NAME  = ''CODIGO_UNIDAD_ARTPROP''
);
SET @ddl := IF(@col_exists = 0,
  ''ALTER TABLE `fza_articulos_propiedades` ''
  ''ADD COLUMN `CODIGO_UNIDAD_ARTPROP` varchar(50) NOT NULL DEFAULT '''''''' ''
  ''  COMMENT ''''FK logica fza_articulos_skus.CODIGO_UNIDAD_SKU. ''
  ''Vacio=articulo; ART/COLOR=color; ART/COLOR/TALLA=sku.'''' ''
  ''  AFTER `CODIGO_PROP_ARTPROP`'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------------------------------------------------------------------------
-- 2. Ampliar la PK para incluir el nivel (CODIGO_UNIDAD_ARTPROP)
--    Antes: (CODIGO_ART_ART, CODIGO_PROP_ARTPROP)
--    Ahora: (CODIGO_ART_ART, CODIGO_PROP_ARTPROP, CODIGO_UNIDAD_ARTPROP)
-- ---------------------------------------------------------------------------
SET @pk_tiene_unidad := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_articulos_propiedades''
     AND INDEX_NAME   = ''PRIMARY''
     AND COLUMN_NAME  = ''CODIGO_UNIDAD_ARTPROP''
);
SET @ddl := IF(@pk_tiene_unidad = 0,
  ''ALTER TABLE `fza_articulos_propiedades` ''
  ''DROP PRIMARY KEY, ''
  ''ADD PRIMARY KEY (`CODIGO_ART_ART`,`CODIGO_PROP_ARTPROP`,`CODIGO_UNIDAD_ARTPROP`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------------------------------------------------------------------------
-- 3. Indice por unidad (busqueda inversa: todas las props de un color/sku),
--    analogo a IDX_FOT_SKU de fotos.
-- ---------------------------------------------------------------------------
SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_articulos_propiedades''
     AND INDEX_NAME   = ''IDX_ARTPROP_UNIDAD''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_articulos_propiedades` ''
  ''ADD INDEX `IDX_ARTPROP_UNIDAD` (`CODIGO_UNIDAD_ARTPROP`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------------------------------------------------------------------------
-- 4. Flag NIVEL_PROP en fza_propiedades: hasta que nivel admite desglose cada
--    propiedad. Dominio: ''ARTICULO'' (por defecto) < ''COLOR'' < ''SKU''.
--    ''COLOR'' implica que se puede fijar a nivel articulo y color.
--    ''SKU''    implica los tres niveles.
-- ---------------------------------------------------------------------------
SET @col_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_propiedades''
     AND COLUMN_NAME  = ''NIVEL_PROP''
);
SET @ddl := IF(@col_exists = 0,
  ''ALTER TABLE `fza_propiedades` ''
  ''ADD COLUMN `NIVEL_PROP` varchar(10) NOT NULL DEFAULT ''''ARTICULO'''' ''
  ''  COMMENT ''''Nivel maximo de desglose: ARTICULO < COLOR < SKU'''' ''
  ''  AFTER `TIPO_VALOR_PROP`'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------------------------------------------------------------------------
-- 5. TEMPORADA pasa a admitir nivel COLOR (idempotente: solo si sigue siendo
--    ARTICULO no la pisa si manana se sube a SKU a mano).
-- ---------------------------------------------------------------------------
UPDATE `fza_propiedades`
   SET `NIVEL_PROP` = ''COLOR''
 WHERE `CODIGO_PROP_ARTPROP` = ''TEMPORADA''
   AND `NIVEL_PROP` = ''ARTICULO'';

-- ---------------------------------------------------------------------------
-- 6. Vista de resolucion efectiva por SKU.
--    Para cada SKU activo y cada propiedad que el articulo tenga a cualquier
--    nivel, devuelve el valor vigente con su origen (SKU/COLOR/ARTICULO),
--    mismo patron COALESCE-por-especificidad que vi_articulos_tarifas.
--    El consumidor (informe / stock / estadistica) filtra por
--    CODIGO_PROP_ARTPROP = ''TEMPORADA''.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW `vi_articulos_propiedades_efectivas` AS
SELECT
  sku.CODIGO_ART_SKU                                   AS CODIGO_ART,
  sku.CODIGO_UNIDAD_SKU                                AS CODIGO_UNIDAD_SKU,
  pr.CODIGO_PROP_ARTPROP                               AS CODIGO_PROP_ARTPROP,
  COALESCE(ps.ID_PV_ARTPROP, pc.ID_PV_ARTPROP,
           pa.ID_PV_ARTPROP)                           AS ID_PV_ARTPROP,
  COALESCE(ps.VALOR_LIBRE_ARTPROP, pc.VALOR_LIBRE_ARTPROP,
           pa.VALOR_LIBRE_ARTPROP)                     AS VALOR_LIBRE_ARTPROP,
  pv.PV                                                AS VALOR_PV,
  CASE WHEN ps.CODIGO_ART_ART IS NOT NULL THEN ''SKU''
       WHEN pc.CODIGO_ART_ART IS NOT NULL THEN ''COLOR''
       WHEN pa.CODIGO_ART_ART IS NOT NULL THEN ''ARTICULO''
       ELSE NULL END                                   AS ORIGEN_PROP
FROM fza_articulos_skus sku
JOIN (SELECT DISTINCT CODIGO_ART_ART, CODIGO_PROP_ARTPROP
        FROM fza_articulos_propiedades) pr
  ON pr.CODIGO_ART_ART = sku.CODIGO_ART_SKU
LEFT JOIN fza_articulos_propiedades ps
       ON ps.CODIGO_ART_ART        = sku.CODIGO_ART_SKU
      AND ps.CODIGO_PROP_ARTPROP   = pr.CODIGO_PROP_ARTPROP
      AND ps.CODIGO_UNIDAD_ARTPROP = sku.CODIGO_UNIDAD_SKU
LEFT JOIN fza_articulos_propiedades pc
       ON pc.CODIGO_ART_ART        = sku.CODIGO_ART_SKU
      AND pc.CODIGO_PROP_ARTPROP   = pr.CODIGO_PROP_ARTPROP
      AND pc.CODIGO_UNIDAD_ARTPROP = CASE
            WHEN CHAR_LENGTH(sku.CODIGO_UNIDAD_SKU)
               - CHAR_LENGTH(REPLACE(sku.CODIGO_UNIDAD_SKU, ''/'', '''')) >= 2
            THEN SUBSTRING_INDEX(sku.CODIGO_UNIDAD_SKU, ''/'', 2)
            ELSE NULL END
LEFT JOIN fza_articulos_propiedades pa
       ON pa.CODIGO_ART_ART        = sku.CODIGO_ART_SKU
      AND pa.CODIGO_PROP_ARTPROP   = pr.CODIGO_PROP_ARTPROP
      AND pa.CODIGO_UNIDAD_ARTPROP = ''''
LEFT JOIN fza_propiedades_valores pv
       ON pv.ID_PV_ARTPROP = COALESCE(ps.ID_PV_ARTPROP, pc.ID_PV_ARTPROP,
                                      pa.ID_PV_ARTPROP)
WHERE sku.ESACTIVO_SKU = ''S'';

