     NUMERO_FAC_VFCOLA               varchar(20) NOT NULL,
     TIPO_OPERACION_VFCOLA           varchar(20) NOT NULL DEFAULT ''''ALTA''''
       COMMENT ''''ALTA o ANULACION'''',
