-- Tabla: fza_inventarios_recuentos

DROP TABLE IF EXISTS `fza_inventarios_recuentos`;
CREATE TABLE `fza_inventarios_recuentos` (
  `ID_INVREC` bigint(20) NOT NULL AUTO_INCREMENT,
  `UUID_INVREC` varchar(36) NOT NULL,
  `CODIGO_EMP_INVREC` varchar(10) NOT NULL,
  `CODIGO_ALM_INVREC` varchar(10) NOT NULL,
  `SERIE_INV_INVREC` varchar(20) NOT NULL,
  `NUMERO_INV_INVREC` varchar(20) NOT NULL,
  `CODIGO_ART_INVREC` varchar(20) NULL DEFAULT NULL,
  `CODIGO_UNIDAD_INVREC` varchar(50) NULL DEFAULT NULL,
  `CODIGO_BARRAS_INVREC` varchar(50) NULL DEFAULT NULL,
  `CANTIDAD_INVREC` decimal(19,6) NOT NULL DEFAULT '1.000000',
  `LOTE_INVREC` varchar(50) NULL DEFAULT '',
  `FECHA_CADUCIDAD_INVREC` date NULL DEFAULT NULL,
  `INSTANTE_RECUENTO_INVREC` datetime NOT NULL,
  `OPERARIO_INVREC` varchar(100) NULL DEFAULT NULL,
  `DISPOSITIVO_INVREC` varchar(100) NULL DEFAULT NULL,
  `ZONA_INVREC` varchar(100) NULL DEFAULT NULL,
  `ESANULADO_INVREC` char(1) NOT NULL DEFAULT 'N',
  `INSTANTE_ALTA` datetime NOT NULL,
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `INSTANTE_MODIF` datetime NULL DEFAULT NULL,
  `USUARIO_MODIF` varchar(100) NULL DEFAULT NULL,
  PRIMARY KEY (`ID_INVREC`)
);
ALTER TABLE `fza_inventarios_recuentos` ADD INDEX `IDX_INVREC_DOC` (`CODIGO_EMP_INVREC`, `CODIGO_ALM_INVREC`, `SERIE_INV_INVREC`, `NUMERO_INV_INVREC`);
ALTER TABLE `fza_inventarios_recuentos` ADD INDEX `IDX_INVREC_UNIDAD` (`CODIGO_UNIDAD_INVREC`);
ALTER TABLE `fza_inventarios_recuentos` ADD UNIQUE INDEX `UQ_INVREC_UUID` (`UUID_INVREC`);


-- Tabla: fza_ivas

DROP TABLE IF EXISTS `fza_ivas`;
CREATE TABLE `fza_ivas` (
  `CODIGO_IVA` varchar(20) NOT NULL DEFAULT '0',
  `IVA_IVAGRP` varchar(10) NOT NULL,
  `DESCRIPCION_IVA_IVAGRP` varchar(100) NOT NULL,
  `PORCENTAJE_EXENTO_IVA` decimal(18,6) unsigned NOT NULL DEFAULT '0.000000',
  `PORCENTAJE_EXENTO_RE_IVA` decimal(18,6) unsigned NOT NULL DEFAULT '0.000000',
  `PORCENTAJE_NORMAL_IVA` decimal(18,6) unsigned NOT NULL DEFAULT '0.000000',
  `PORCENTAJE_NORMAL_RE_IVA` decimal(18,6) unsigned NOT NULL DEFAULT '0.000000',
  `PORCENTAJE_REDUCIDO_IVA` decimal(18,6) unsigned NOT NULL DEFAULT '0.000000',
  `PORCENTAJE_REDUCIDO_RE_IVA` decimal(18,6) unsigned NOT NULL DEFAULT '0.000000',
  `PORCENTAJE_SUPERREDUCIDO_IVA` decimal(18,6) unsigned NOT NULL DEFAULT '0.000000',
  `PORCENTAJE_SUPERREDUCIDO_RE_IVA` decimal(18,6) unsigned NOT NULL DEFAULT '0.000000',
  `FECHA_DESDE_IVA` date NOT NULL,
  `FECHA_HASTA_IVA` date NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_IVA`)
);

