-- Tabla: fza_propiedades_valores

DROP TABLE IF EXISTS `fza_propiedades_valores`;
CREATE TABLE `fza_propiedades_valores` (
  `ID_PV_ARTPROP` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Identificador único del valor de la propiedad',
  `ID_PROP_PV` varchar(20) NOT NULL COMMENT 'FK hacia fza_propiedades (ej: MATERIAL, EDAD_MAX)',
  `PV` varchar(100) NOT NULL COMMENT 'El valor real (ej: Acero Inoxidable, +3 años, Lego)',
  `DESCRIPCION_PV` varchar(255) NULL DEFAULT NULL COMMENT 'Descripción comercial ampliada si es necesaria',
  `ESACTIVO_PV` varchar(1) NULL DEFAULT 'S' COMMENT 'S para activo, N para inactivo',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`ID_PV_ARTPROP`)
);
ALTER TABLE `fza_propiedades_valores` ADD INDEX `IDX_PROPIEDAD_PV` (`ID_PROP_PV`);

