  `POBLACION_PRV` varchar(200) NULL DEFAULT NULL,
  `PROVINCIA_PRV` varchar(200) NULL DEFAULT NULL,
  `CODIGO_POSTAL_PRV` varchar(15) NULL DEFAULT NULL,
  `PAIS_PRV` varchar(150) NULL DEFAULT NULL,
