  `TELEFONO_CONTACTO_PRV` varchar(100) NULL DEFAULT NULL,
  `TELEFONO_PRV` varchar(40) NULL DEFAULT NULL,
  `IBAN_PRV` varchar(100) NULL DEFAULT NULL,
